import type { Lang } from "./types";

/**
 * Researched artist biographies.
 *
 * The project's content rule applies here more sharply than anywhere else: these are
 * real, living people. A plausible-sounding bio assembled from a model's memory gets
 * nationalities, labels and dates wrong, and being wrong about a person in public is a
 * different class of mistake from being wrong about a ticket price. So every entry is
 * researched from a citable source and carries it in `sources`; an artist we could not
 * verify simply has no entry, and their page keeps showing dates without a bio — the
 * same way an event with no announced line-up says so rather than inventing one.
 *
 * `bio` is two to four sentences, French first (the source of truth) and English for
 * `/en`. Facts only: where they are from, what they play, what they are known for.
 * No superlatives we cannot source, no "one of the most influential artists of his
 * generation" — that sentence is true of nobody and printable about everybody.
 */
export interface ArtistBio {
  /** Matches `Artist.slug` from lib/artists.ts (i.e. `slugify(name)`). */
  slug: string;
  bio: { fr: string; en: string };
  /** Country or city the artist is from, as stated by the source. */
  origin?: string;
  /** Year they started releasing/performing, when a source gives one. */
  since?: number;
  /** Labels, when documented — a strong relevance signal for the genre pages. */
  labels?: string[];
  /** URLs the facts came from. Never empty: no source, no entry. */
  sources: string[];
  /**
   * Avatar, and the credit that legally has to travel with it.
   *
   * Sourced from Wikimedia Commons only. A press-kit or Instagram shot is a
   * copyrighted work whoever publishes it, and "press use" is not a licence to
   * illustrate a directory. Commons states its terms, and most of its photos are
   * CC BY / CC BY-SA — which permit reuse *provided* the author and licence are
   * shown. Hence `credit`: it is not decoration, it is the condition of use, and
   * `ArtistPage` renders it under the portrait.
   */
  photo?: {
    /** Local file under /artists/, produced by .research/artists/avatars.py. */
    file: string;
    /** Author / credit line exactly as Commons states it. */
    author: string;
    /** Licence short name, e.g. "CC BY-SA 4.0". */
    license: string;
    /** Commons file page, so a reader can check the terms themselves. */
    page: string;
  };
}

/* BIOS:start — generated by .research/artists/ingest.py, do not edit by hand */
export const BIOS: Record<string, ArtistBio> = {
  "999999999": { slug: "999999999", bio: { fr: "999999999 est un duo italien de hard techno formé en 2016, qui se produit exclusivement en live et uniquement au matériel analogique. Le duo a d'abord publié ses disques en vinyle seul sur son propre label NineTimesNine, avant de passer au numérique en 2020. Son morceau « 300000003 », sorti sur Planet Rhythm en 2018, a été repressé à plusieurs reprises et a fait connaître sa techno acide à un large public. Le duo organise aussi ses propres soirées 9x9 Invites en Europe.", en: "999999999 are an Italian hard techno duo formed in 2016 who perform exclusively as a hardware-only live act. They first put out records as a vinyl-only operation on their own NineTimesNine label before moving to digital in 2020. Their track \"300000003\", released on Planet Rhythm in 2018, went through repeated represses and brought their acid techno to a much wider audience. The pair also run their own 9x9 Invites parties across Europe." }, origin: "Italie", since: 2016, labels: ["NineTimesNine"], sources: ["https://www.awakenings.com/en/artists/999999999/1658/"] }, // 999999999
  "acid-arab": { slug: "acid-arab", bio: { fr: "Acid Arab est un groupe français d'électronique formé à Paris en 2012 par les DJ Guido Minisky et Hervé Carvalho, rejoints par Pierrot Casanova, Nicolas Borne et le claviériste Kenzi Bourras. Le projet greffe des structures rythmiques et des mélodies orientales et amazighes — raï algérien, chaâbi égyptien — sur une base d'acid house et de techno. Ils publient chez le label belge Crammed Discs, où sont parus « Musique de France » en 2016 et « Jdid » en 2019, après des premiers disques sur Versatile. Ils ont enregistré avec Omar Souleyman, Rachid Taha et Les Filles de Illighadad.", en: "Acid Arab are a French electronic group formed in Paris in 2012 by DJs Guido Minisky and Hervé Carvalho, later joined by Pierrot Casanova, Nicolas Borne and keyboard player Kenzi Bourras. The project grafts Middle Eastern and Amazigh rhythms and melodies — Algerian raï, Egyptian chaâbi — onto a base of acid house and techno. They record for the Belgian label Crammed Discs, home to \"Musique de France\" (2016) and \"Jdid\" (2019), after early records on Versatile. They have worked with Omar Souleyman, Rachid Taha and Les Filles de Illighadad." }, origin: "Paris, France", since: 2012, labels: ["Crammed Discs", "Versatile"], sources: ["https://fr.wikipedia.org/wiki/Acid_Arab"] }, // Acid Arab
  "adam-beyer": { slug: "adam-beyer", bio: { fr: "Adam Beyer, né le 15 mai 1976 à Stockholm, est un DJ et producteur suédois de techno. Il a fondé en 1996 le label Drumcode, devenu l'une des principales structures techno européennes, dont le catalogue accueille Amelie Lens, Joseph Capriati ou Pan-Pot. Il anime également l'émission hebdomadaire Drumcode Radio Live.", en: "Adam Beyer, born 15 May 1976 in Stockholm, is a Swedish techno DJ and producer. In 1996 he founded the Drumcode label, now one of Europe's major techno imprints, whose roster includes Amelie Lens, Joseph Capriati and Pan-Pot. He also hosts the weekly Drumcode Radio Live show." }, origin: "Stockholm, Suède", labels: ["Drumcode"], sources: ["https://en.wikipedia.org/wiki/Adam_Beyer", "https://en.wikipedia.org/wiki/Drumcode_Records"], photo: { file: "adam-beyer.webp", author: "Flickr user 70048083@N00", license: "CC BY 2.0", page: "https://commons.wikimedia.org/wiki/File:Adam_Beyer_(3559941164).jpg" } }, // Adam Beyer
  "adriatique": { slug: "adriatique", bio: { fr: "Adriatique est un duo suisse formé par Adrian Shala et Adrian Schweizer — le nom vient de leur prénom commun. Ils se rencontrent en 2008 dans les clubs du pays et produisent ensemble depuis 2009 une house et une techno mélodiques et atmosphériques. Rattachés au label Diynamic de Solomun, ils fondent leur propre structure Siamese en 2016 et publient en septembre 2018 leur album Nude sur Afterlife, le label de Tale of Us.", en: "Adriatique is a Swiss duo made up of Adrian Shala and Adrian Schweizer — the name comes from their shared first name. They met in 2008 on the local club scene and have been producing melodic, atmospheric house and techno together since 2009. Affiliated with Solomun's Diynamic label, they founded their own imprint Siamese in 2016 and released their album Nude on Tale of Us's Afterlife in September 2018." }, origin: "Suisse", since: 2009, labels: ["Siamese", "Afterlife", "Diynamic"], sources: ["https://en.wikipedia.org/wiki/Adriatique"] }, // Adriatique
  "alignment": { slug: "alignment", bio: { fr: "Alignment est le projet de Francesco Pierfelici, DJ et producteur italien né en 1992 et installé à Berlin. Il dit avoir découvert la techno au Cocoricò de Riccione, et lance son alias en juillet 2015 : sa hard techno rapide et sans répit lui vaut le soutien de Ben Klock, Amelie Lens ou Richie Hawtin. Il est signé chez Voxnox depuis 2014 et publie aussi sur KNTXT, le label de Charlotte de Witte, ainsi que sur Involve Records, ARTS et Etruria Beat.", en: "Alignment is the project of Francesco Pierfelici, an Italian DJ and producer born in 1992 and based in Berlin. He says he discovered techno at the Cocoricò club in Riccione, and launched the alias in July 2015; his fast, relentless hard techno has drawn support from Ben Klock, Amelie Lens and Richie Hawtin. He has been signed to Voxnox since 2014 and also releases on Charlotte de Witte's KNTXT, as well as Involve Records, ARTS and Etruria Beat." }, origin: "Italie, installé à Berlin", since: 2015, labels: ["Voxnox", "KNTXT"], sources: ["https://www.beatportal.com/articles/464385-beatport-next-the-power-of-alignment", "https://electronicgroove.com/interview-alignment/"] }, // Alignment
  "amelie-lens": { slug: "amelie-lens", bio: { fr: "Amelie Lens, née le 31 mai 1990 à Vilvorde et installée à Anvers, est une DJ et productrice belge de techno. Ancienne mannequin, elle abandonne la mode en 2014 pour mixer, d'abord sous le nom de Renée, puis sort son premier EP, Exhale, en 2016 avant de signer sur Second State. Elle dirige aujourd'hui les labels Lenske et Exhale, ce dernier donnant aussi son nom à sa série d'événements.", en: "Amelie Lens, born 31 May 1990 in Vilvoorde and based in Antwerp, is a Belgian techno DJ and producer. A former model, she left fashion in 2014 to DJ, first under the name Renée, then released her first EP, Exhale, in 2016 before signing to Second State. She now runs the labels Lenske and Exhale, the latter also lending its name to her event series." }, origin: "Vilvorde / Anvers, Belgique", since: 2014, labels: ["Lenske", "Exhale", "Second State"], sources: ["https://fr.wikipedia.org/wiki/Amelie_Lens", "https://en.wikipedia.org/wiki/Amelie_Lens"] }, // Amelie Lens
  "andres-campo": { slug: "andres-campo", bio: { fr: "Andrés Campo est un DJ et producteur espagnol originaire de Huesca, en Aragon. Il joue de la techno, de la tech house et de la minimal techno, et a commencé comme résident de petits clubs de sa ville natale avant de tourner dans toute l'Espagne. Il a cofondé en 2019 le label EI8HT avec le Britannique Eats Everything, orienté vers une techno de groove plutôt que de martèlement. Il est aussi à l'origine du Raspafestival, à Huesca, et de Global Music, lancé à Saragosse en 2010.", en: "Andrés Campo is a Spanish DJ and producer from Huesca, in Aragon. He plays techno, tech house and minimal techno, and started out as a resident in small clubs in his home town before touring across Spain. In 2019 he co-founded the EI8HT label with Britain's Eats Everything, aimed at groove-led techno rather than relentless hammering. He is also behind the Raspafestival in Huesca and Global Music, launched in Zaragoza in 2010." }, origin: "Huesca, Espagne", labels: ["EI8HT"], sources: ["https://fanmusicfest.com/content/andres-campo", "https://www.magneticmag.com/2019/03/eats-everything-andres-campo-launch-new-label-ei8ht/"] }, // Andrés Campo
  "anetha": { slug: "anetha", bio: { fr: "Anetha est une DJ et productrice française née en 1989 à Bordeaux et installée à Paris. Passée par des études d'architecture et initiée aux platines à seize ans, elle défend une techno acide et hypnotique dont « Acid Train » (2017) reste le morceau signature. Elle a fondé en 2019 le label et collectif Mama Told Ya, et a mixé à la cérémonie de clôture des Jeux paralympiques de Paris en 2024.", en: "Anetha is a French DJ and producer born in Bordeaux in 1989 and based in Paris. Trained as an architect and behind the decks since she was sixteen, she plays acid-leaning, hypnotic techno, with \"Acid Train\" (2017) still her signature track. She founded the label and collective Mama Told Ya in 2019, and played the closing ceremony of the 2024 Paris Paralympic Games." }, origin: "Bordeaux, France", since: 2013, labels: ["Mama Told Ya"], sources: ["https://fr.wikipedia.org/wiki/Anetha"] }, // Anetha
  "angerfist": { slug: "angerfist", bio: { fr: "Angerfist, de son vrai nom Danny Masseling, né le 20 juin 1981 à Almere, est un producteur et DJ néerlandais de hardcore. Il publie son premier EP, Criminally Insane, en 2002, puis son premier album, Pissin' Razorbladez, en 2006. Il se produit derrière un masque de hockey blanc, accompagné sur scène par MC Prozac depuis 2006.", en: "Angerfist, real name Danny Masseling, born 20 June 1981 in Almere, is a Dutch hardcore producer and DJ. He released his first EP, Criminally Insane, in 2002, followed by his first album, Pissin' Razorbladez, in 2006. He performs behind a white hockey mask, joined on stage by MC Prozac since 2006." }, origin: "Almere, Pays-Bas", since: 2002, labels: ["Masters of Hardcore"], sources: ["https://fr.wikipedia.org/wiki/Angerfist", "https://en.wikipedia.org/wiki/Angerfist"], photo: { file: "angerfist.webp", author: "JoeJoeJoe93", license: "CC BY-SA 3.0", page: "https://commons.wikimedia.org/wiki/File:Angerfist_(17)_(cropped).JPG" } }, // Angerfist
  "armin-van-buuren": { slug: "armin-van-buuren", bio: { fr: "Armin van Buuren est un DJ et producteur néerlandais né en 1976 à Leyde, figure de la trance. Il a commencé à mixer au Club Nexus en 1996, en parallèle de ses études de droit à l'université de Leyde. Son émission « A State of Trance », lancée en mars 2001, est diffusée dans 84 pays. Il a fondé le label indépendant Armada Music, a été élu numéro un du Top 100 DJs de DJ Mag à cinq reprises entre 2007 et 2012, et a été fait officier de l'ordre d'Orange-Nassau en 2011.", en: "Armin van Buuren is a Dutch DJ and producer born in Leiden in 1976, a central figure in trance. He started DJing at Club Nexus in 1996 while studying law at Leiden University. His radio show \"A State of Trance\", launched in March 2001, is broadcast in 84 countries. He founded the independent label Armada Music, topped DJ Mag's Top 100 DJs poll five times between 2007 and 2012, and was appointed Officer of the Order of Orange-Nassau in 2011." }, origin: "Leyde, Pays-Bas", since: 1996, labels: ["Armada Music"], sources: ["https://en.wikipedia.org/wiki/Armin_van_Buuren"], photo: { file: "armin-van-buuren.webp", author: "Web Summit / Sam Barnes / Sportsfile", license: "CC BY 4.0", page: "https://commons.wikimedia.org/wiki/File:Armin_van_Buuren,_November_2025_(cropped).jpg" } }, // Armin van Buuren
  "autechre": { slug: "autechre", bio: { fr: "Autechre est un duo anglais de musique électronique formé en 1987 à Rochdale, près de Manchester, par Rob Brown et Sean Booth. Tous leurs albums paraissent chez Warp Records, à commencer par Incunabula en 1993, après leur apparition sur la compilation Artificial Intelligence en 1992. Partis d'une techno mélodique influencée par l'électro et le hip-hop des années 1980, ils ont évolué vers des compositions abstraites souvent rattachées à l'IDM.", en: "Autechre are an English electronic duo formed in 1987 in Rochdale, near Manchester, by Rob Brown and Sean Booth. All their albums have appeared on Warp Records, starting with Incunabula in 1993, after their appearance on the 1992 compilation Artificial Intelligence. Starting from melodic techno shaped by 1980s electro and hip-hop, they moved towards abstract compositions often filed under IDM." }, origin: "Rochdale, Angleterre", since: 1987, labels: ["Warp Records"], sources: ["https://en.wikipedia.org/wiki/Autechre"], photo: { file: "autechre.webp", author: "Flickr user 71875951@N00", license: "CC BY-SA 2.0", page: "https://commons.wikimedia.org/wiki/File:Autechre_(cropped).jpg" } }, // Autechre
  "bashkka": { slug: "bashkka", bio: { fr: "DJ et productrice née et installée à Munich, résidente du Blitz Club, elle croise une house et une techno rapides avec des samples vocaux kurdes et une bounce house d'inspiration chicagoane qu'elle chante elle-même. Militante trans, elle a publié son premier EP solo, Maktub, sur UMAY, le label à but non lucratif fondé par Nene H, et est représentée par l'agence de booking de Marcel Dettmann.", en: "A DJ and producer born and based in Munich and a resident at the Blitz Club, she crosses fast house and techno with Kurdish vocal samples and a Chicago-flavoured bounce house she sings herself. A trans activist, she released her first solo EP, Maktub, on UMAY, the non-profit label founded by Nene H, and is represented by Marcel Dettmann's booking agency." }, origin: "Munich, Allemagne", labels: ["UMAY"], sources: ["https://djmag.com/news/nene-h-launches-new-label-umay-bashkka-ep", "https://www.playfulmag.com/post/bashkka-not-just-a-hype"] }, // BASHKKA
  "ben-klock": { slug: "ben-klock", bio: { fr: "Ben Klock, né en 1972 à Berlin-Ouest, est un DJ et producteur allemand de techno. Pianiste dans l'enfance, il sort son premier disque, Clockworks EP, en 1998 sur Sonar Kollektiv, puis devient résident du Berghain peu après l'ouverture du club en 2004. Il fonde le label Klockworks en 2006 et publie son album One sur Ostgut Ton en 2009.", en: "Ben Klock, born in 1972 in West Berlin, is a German techno DJ and producer. A pianist as a child, he released his first record, Clockworks EP, on Sonar Kollektiv in 1998, then became a resident at Berghain shortly after the club opened in 2004. He founded the Klockworks label in 2006 and released his album One on Ostgut Ton in 2009." }, origin: "Berlin, Allemagne", since: 1998, labels: ["Klockworks", "Ostgut Ton"], sources: ["https://fr.wikipedia.org/wiki/Ben_Klock", "https://en.wikipedia.org/wiki/Ben_Klock"] }, // Ben Klock
  "ben-sims": { slug: "ben-sims", bio: { fr: "Ben Sims, de son vrai nom Ben Stocker, est un DJ et producteur de techno britannique installé à Londres. Il a fondé les labels Theory Recordings, Hardgroove, Machine, Ingoma et Symbolism, et copilote le studio Hardgroove Mastering avec Paul Mac. Ses disques sont parus chez Tresor, Drumcode, Mosaic, Bass Culture et CLR, et il a signé des remixes pour Jeff Mills, Robert Hood, Kevin Saunderson, Carl Cox et Adam Beyer.", en: "Ben Sims, real name Ben Stocker, is a British techno DJ and producer based in London. He founded the labels Theory Recordings, Hardgroove, Machine, Ingoma and Symbolism, and co-runs the Hardgroove Mastering studio with Paul Mac. His records have appeared on Tresor, Drumcode, Mosaic, Bass Culture and CLR, and he has remixed Jeff Mills, Robert Hood, Kevin Saunderson, Carl Cox and Adam Beyer." }, origin: "Londres, Royaume-Uni", labels: ["Theory Recordings", "Hardgroove", "Symbolism", "Ingoma"], sources: ["https://bensims.bandcamp.com/", "https://www.discogs.com/artist/3947"] }, // Ben Sims
  "benny-rodrigues": { slug: "benny-rodrigues", bio: { fr: "Benny Rodrigues est un DJ et producteur néerlandais né à Rotterdam en 1982, d'origine portugaise. Sous son propre nom il joue de la house et de la tech house ; depuis 2011 il utilise le pseudonyme ROD pour ses productions techno, décrites comme profondes et répétitives, entre Detroit, Berlin, acid et dub. Son EP « Malmok » est sorti sur Klockworks, le label de Ben Klock, et il a ensuite publié sur CLR, M_nus et Drumcode. Il est connu pour ses sets marathon, notamment au Berghain et au Trouw.", en: "Benny Rodrigues is a Dutch DJ and producer born in Rotterdam in 1982, of Portuguese descent. Under his own name he plays house and tech house; since 2011 he has used the alias ROD for his techno productions, described as deep and repetitive, drawing on Detroit, Berlin, acid and dub. His \"Malmok\" EP came out on Ben Klock's Klockworks label, and he has since released on CLR, M_nus and Drumcode. He is known for marathon sets, notably at Berghain and Trouw." }, origin: "Rotterdam, Pays-Bas", since: 2011, labels: ["Klockworks", "Drumcode"], sources: ["https://nl.wikipedia.org/wiki/Benny_Rodrigues"] }, // Benny Rodrigues
  "biianco": { slug: "biianco", bio: { fr: "BIIANCO est un projet de production et de DJing né à New York, passé par Los Angeles et aujourd'hui basé à Londres, mené par un·e multi-instrumentiste qui utilise le pronom « they ». Le son tourne entre 140 et 150 BPM : acid, trance et techno mâtinés de house et de pop, en partie joués en direct aux claviers et aux percussions. Sur Ultra Records est paru le single « Get You Out » en 2024, après des collaborations avec Marlon Hoffstadt. BIIANCO se revendique queer, neurodivergent·e et handicapé·e, et milite pour l'inclusion dans l'industrie musicale.", en: "BIIANCO is a producer, DJ and multi-instrumentalist born in New York, trained in Los Angeles and now based in London. They play acid, trance and techno laced with house and pop at 140–150 BPM, performing part of it live on keys and percussion. Signed to Ultra Records, they released the single \"Get You Out\" there in 2024 and have collaborated with Marlon Hoffstadt. A queer, neurodivergent and disabled artist, they campaign for inclusion in the music industry." }, origin: "New York, États-Unis", since: 2019, labels: ["Ultra Records"], sources: ["https://djmag.com/features/studio-biianco"] }, // Biianco
  "bob-sinclar": { slug: "bob-sinclar", bio: { fr: "Christophe Le Friant, né en 1969 à Paris, cofonde le label Yellow Productions au début des années 1990 et fait partie des producteurs de la French touch. Après « Gym Tonic » (1998), réalisé avec Thomas Bangalter, il enchaîne les succès house « Love Generation » (2005), « World, Hold On » et « Rock This Party » (2006). Il pilote également le collectif Africanism All Stars.", en: "Christophe Le Friant, born in Paris in 1969, co-founded the Yellow Productions label in the early 1990s and belongs to the French touch generation of producers. After \"Gym Tonic\" (1998), made with Thomas Bangalter, he lined up the house hits \"Love Generation\" (2005), \"World, Hold On\" and \"Rock This Party\" (2006). He also steers the Africanism All Stars collective." }, origin: "Paris, France", since: 1992, labels: ["Yellow Productions"], sources: ["https://fr.wikipedia.org/wiki/Bob_Sinclar"], photo: { file: "bob-sinclar.webp", author: "CamilaAlves.raf", license: "CC BY-SA 4.0", page: "https://commons.wikimedia.org/wiki/File:Bob_Sinclar_at_Pal%C3%A9o_Festival_2026-2.jpg" } }, // Bob Sinclar
  "boris-brejcha": { slug: "boris-brejcha", bio: { fr: "Boris Brejcha, né le 26 novembre 1981 à Ludwigshafen, est un DJ et producteur allemand. Il qualifie lui-même son style de « high-tech minimal » et se produit derrière un masque de joker inspiré du carnaval de Venise. Il a cofondé en 2015 le label Fckng Serious avec Ann Clue et Deniz Bul, et a sorti l'album Space Diver en janvier 2020.", en: "Boris Brejcha, born 26 November 1981 in Ludwigshafen, is a German DJ and producer. He calls his own style \"high-tech minimal\" and performs behind a joker mask based on a Carnival of Venice design. He co-founded the label Fckng Serious in 2015 with Ann Clue and Deniz Bul, and released the album Space Diver in January 2020." }, origin: "Ludwigshafen, Allemagne", labels: ["Fckng Serious", "Ultra Records"], sources: ["https://en.wikipedia.org/wiki/Boris_Brejcha"], photo: { file: "boris-brejcha.webp", author: "Gauvain", license: "CC BY-SA 4.0", page: "https://commons.wikimedia.org/wiki/File:Boris_brejcha_2017_03_12.jpg" } }, // Boris Brejcha
  "boss-priester": { slug: "boss-priester", bio: { fr: "Boss Priester est un producteur et DJ néerlandais installé à La Haye, qui joue un mélange de minimal, de house et de techno. Ses disques sont parus sur Ba Dum Tish, Dungeon Meat, Locus et Interweaved Records, et il gère en parallèle son propre label de dubplates, BPDUBS. Son travail est relayé par Enzo Siragusa, Alec Falconer ou Dr. Banana.", en: "Boss Priester is a Dutch producer and DJ based in The Hague who plays a mix of minimal, house and techno. His records have come out on Ba Dum Tish, Dungeon Meat, Locus and Interweaved Records, and he runs his own dubplate label, BPDUBS. His work is championed by the likes of Enzo Siragusa, Alec Falconer and Dr. Banana." }, origin: "La Haye, Pays-Bas", labels: ["BPDUBS", "Locus", "Ba Dum Tish"], sources: ["https://bosspriester.bandcamp.com/", "https://events.musicofourdesire.com/artist/boss-priester"] }, // Boss Priester
  "calvin-harris": { slug: "calvin-harris", bio: { fr: "Calvin Harris, de son vrai nom Adam Richard Wiles, est un DJ, producteur et chanteur écossais né en 1984 à Dumfries. Son premier album, « I Created Disco », est sorti en 2007 ; ont suivi « We Found Love » avec Rihanna, « Summer » et « How Deep Is Your Love ». Il détient le record du plus grand nombre de numéros un au Royaume-Uni dans les années 2010 et a placé neuf singles dans le top 10 britannique à partir du seul album « 18 Months ». Il a fondé le label Fly Eye Records en mars 2010.", en: "Calvin Harris, real name Adam Richard Wiles, is a Scottish DJ, producer and singer born in Dumfries in 1984. His first album, \"I Created Disco\", came out in 2007; \"We Found Love\" with Rihanna, \"Summer\" and \"How Deep Is Your Love\" followed. He holds the record for the most UK number-one singles of the 2010s, and pulled nine UK top-ten singles from the album \"18 Months\" alone. He founded the Fly Eye Records label in March 2010." }, origin: "Dumfries, Écosse", since: 2007, labels: ["Fly Eye Records"], sources: ["https://en.wikipedia.org/wiki/Calvin_Harris"], photo: { file: "calvin-harris.webp", author: "Sony BMG", license: "CC BY 3.0", page: "https://commons.wikimedia.org/wiki/File:Calvin_Harris_-_Press_Image_1.tif" } }, // Calvin Harris
  "carista": { slug: "carista", bio: { fr: "Carista, de son vrai nom Carista Eendragt, est une DJ, productrice et curatrice néerlandaise née à Utrecht de parents surinamais. Ses sets circulent entre house italienne, broken beat, garage et techno, avec des racines revendiquées dans le hip-hop et la soul funk. Elle a fondé en 2017 United Identities, à la fois label, série de soirées et émission mensuelle sur NTS Radio, consacrée aux artistes basés aux Pays-Bas. Résidente de Red Light Radio puis de De School, elle a livré un Essential Mix sur BBC Radio 1 en février 2020 et reçu le Gieskes-Strijbis Podiumprijs en 2021.", en: "Carista, born Carista Eendragt, is a Dutch DJ, producer and curator from Utrecht, born to Surinamese parents. Her sets move between Italo house, broken beat, garage and techno, rooted in hip-hop and soul funk. In 2017 she founded United Identities, at once a label, a club night and a monthly NTS Radio show dedicated to Netherlands-based artists. A resident at Red Light Radio and then De School, she delivered a BBC Radio 1 Essential Mix in February 2020 and won the Gieskes-Strijbis Podiumprijs in 2021." }, origin: "Utrecht, Pays-Bas", since: 2012, labels: ["United Identities"], sources: ["https://djmag.com/features/carista-unifying-dancefloor-interview-united-identities"] }, // Carista
  "charlotte-de-witte": { slug: "charlotte-de-witte", bio: { fr: "Charlotte de Witte, née le 21 juillet 1992, est une DJ et productrice belge originaire de Gand. Elle défend une techno sombre et dépouillée, teintée d'acid et de minimale, après avoir débuté sous l'alias Raving George. Elle a fondé les labels KNTXT et Époque, et figure au classement Top 100 DJs de DJ Mag depuis 2019.", en: "Charlotte de Witte, born 21 July 1992, is a Belgian DJ and producer from Ghent. She is known for a dark, stripped-back take on techno drawing on acid and minimal, after starting out under the alias Raving George. She founded the labels KNTXT and Époque, and has charted in DJ Mag's Top 100 DJs since 2019." }, origin: "Gand, Belgique", labels: ["KNTXT", "Époque"], sources: ["https://en.wikipedia.org/wiki/Charlotte_de_Witte"], photo: { file: "charlotte-de-witte.webp", author: "Alan Overbeek", license: "CC BY-SA 4.0", page: "https://commons.wikimedia.org/wiki/File:Charlotte_de_witte-1513626416.jpg" } }, // Charlotte de Witte
  "chlar": { slug: "chlar", bio: { fr: "Chlär est un DJ et producteur suisse installé à Berlin depuis fin 2017. Il joue une techno rapide et percussive, construite sur des boucles de ses propres productions. Il a cofondé en 2017 le label Bipolar Disorder avec Jules Auderset (The Chronics), puis lancé son propre label Primal Instinct en 2023, où est paru son EP « Modern Survival ». Il forme également le duo Funk Assault avec Alarico.", en: "Chlär is a Swiss DJ and producer who has been based in Berlin since late 2017. He plays fast, percussive techno built from loops of his own productions. In 2017 he co-founded the Bipolar Disorder label with Jules Auderset (The Chronics), then launched his own imprint Primal Instinct in 2023, home to his \"Modern Survival\" EP. He also makes up the duo Funk Assault with Alarico." }, origin: "Suisse", since: 2017, labels: ["Primal Instinct", "Bipolar Disorder"], sources: ["https://groove.de/2025/01/08/chlaer-es-ist-einfach-das-verrueckteste-zeug-zu-machen/"] }, // Chlär
  "chloe-caillet": { slug: "chloe-caillet", bio: { fr: "Chloé Caillet est une DJ, productrice et multi-instrumentiste née à Manhattan et arrivée à Paris à onze ans, de mère franco-italienne et de père franco-espagnol. Pianiste classique de formation, elle étudie le jazz en Angleterre puis le music business à l'université de New York, et passe par la promotion de clubs et l'A&R avant de mixer. Son premier EP, Intro, est sorti en mai 2023 sur CircoLoco Records ; elle est résidente du DC-10 à Ibiza et a fondé son label XCESS Records.", en: "Chloé Caillet is a DJ, producer and multi-instrumentalist born in Manhattan who moved to Paris at eleven, with a French-Italian mother and a French-Spanish father. A classically trained pianist, she studied jazz in England and music business at New York University, and worked in club promotion and A&R before DJing. Her first EP, Intro, came out in May 2023 on CircoLoco Records; she is a resident at DC-10 in Ibiza and founded her label XCESS Records." }, origin: "New York / Paris", labels: ["XCESS Records", "CircoLoco Records"], sources: ["https://djmag.com/features/chloe-caillet-modern-fusion-ibiza-interview"] }, // Chloé Caillet
  "chris-stussy": { slug: "chris-stussy", bio: { fr: "Chris Stussy, de son vrai nom Niels Christian Steenbergen, est un DJ et producteur néerlandais né à Leiderdorp et élevé à Leyde. Il fonde son label Up the Stuss en 2020 et a également publié sur Fuse London, PIV et Kaoz Theory. Son single « All Night Long », sorti en 2023, marque son décollage, suivi de sa série de soirées USS lancée à Londres en 2025 et de l'album Lost, Found & Forgotten en 2026.", en: "Chris Stussy, real name Niels Christian Steenbergen, is a Dutch DJ and producer born in Leiderdorp and raised in Leiden. He founded his label Up the Stuss in 2020 and has also released on Fuse London, PIV and Kaoz Theory. His 2023 single \"All Night Long\" was his breakthrough, followed by his USS party series launched in London in 2025 and the album Lost, Found & Forgotten in 2026." }, origin: "Leiderdorp / Leyde, Pays-Bas", since: 2014, labels: ["Up the Stuss", "Fuse London", "PIV"], sources: ["https://en.wikipedia.org/wiki/Chris_Stussy"] }, // Chris Stussy
  "clara-cuve": { slug: "clara-cuve", bio: { fr: "Clara Cuvé est une DJ et productrice allemande née à Munich et installée à Berlin. Pianiste de formation classique, elle a découvert le vinyle à l'adolescence avant de jouer dans les soirées de sa ville. Ses sets passent d'une techno rapide et groovy au breakbeat, à la jungle et à l'électro. Elle est résidente du club berlinois OHM, a lancé en mars 2023 la série de soirées « Sesh » avec MCR-T et a mixé pour le défilé Rick Owens de la London Fashion Week en février de la même année.", en: "Clara Cuvé is a German DJ and producer born in Munich and based in Berlin. A classically trained pianist, she discovered vinyl as a teenager before playing parties in her home city. Her sets move from fast, groovy techno into breakbeat, jungle and electro. She is a resident at the Berlin club OHM, launched the \"Sesh\" party series with MCR-T in March 2023, and played Rick Owens's London Fashion Week show in February of that year." }, origin: "Munich, Allemagne", sources: ["https://www.laweekly.com/clara-cuve-berlins-rising-techno-star-connects-the-generations/"] }, // Clara Cuvé
  "creeds": { slug: "creeds", bio: { fr: "Willy Taconné, producteur et DJ français né en mai 1992, a appris le piano avant de se mettre à la production adolescent. Longtemps rattaché à la frenchcore et à la reverse bass, il a basculé vers la hard techno avec « Push Up », sorti fin 2022 : le titre est devenu viral sur TikTok, a atteint la sixième place des ventes en Allemagne et a été certifié dans une dizaine de pays.", en: "Willy Taconné, a French producer and DJ born in May 1992, learned piano before moving into production as a teenager. Long associated with frenchcore and reverse bass, he swung towards hard techno with \"Push Up\", released in late 2022: the track went viral on TikTok, reached number six on the German singles chart and was certified in around ten countries." }, origin: "France", sources: ["https://fr.wikipedia.org/wiki/Creeds", "https://de.wikipedia.org/wiki/Creeds", "https://fourfourmag.com/in-conversation-with-creeds-i-was-ready-to-give-up-then-push-up-happened/"] }, // Creeds
  "d-block-s-te-fan": { slug: "d-block-s-te-fan", bio: { fr: "D-Block & S-te-Fan est un duo hardstyle néerlandais formé fin 2004 à La Haye par Diederik Bakker (D-Block) et Stefan den Daas (S-te-Fan). Ils ont signé les hymnes officiels de Qlimax en 2009 et de Defqon.1 en 2020, et publié quatre albums, de « Music Made Addictz » (2009) à « Enter Your Mind » (2021). Leur label, Scantraxx Evolutionz, est une filiale de Scantraxx, fondé par The Prophet. Depuis 2015, ils utilisent aussi l'alias DBSTF pour leurs productions big room.", en: "D-Block & S-te-Fan are a Dutch hardstyle duo formed in late 2004 in The Hague by Diederik Bakker (D-Block) and Stefan den Daas (S-te-Fan). They wrote the official anthems for Qlimax in 2009 and Defqon.1 in 2020, and have released four albums, from \"Music Made Addictz\" (2009) to \"Enter Your Mind\" (2021). Their label, Scantraxx Evolutionz, is a sub-label of The Prophet's Scantraxx. Since 2015 they have also used the alias DBSTF for their big room productions." }, origin: "La Haye, Pays-Bas", since: 2004, labels: ["Scantraxx Evolutionz"], sources: ["https://fr.wikipedia.org/wiki/D-Block_%26_S-te-Fan"] }, // D-Block & S-te-Fan
  "da-tweekaz": { slug: "da-tweekaz", bio: { fr: "Da Tweekaz est un duo hardstyle norvégien formé par Kenth Kvien et Marcus Nordli, actif depuis la fin des années 2000 et installé en Belgique depuis 2012 pour se rapprocher des festivals du Benelux. Leurs disques paraissent chez Dirty Workz, et le premier album Time 2 Shine date de 2012. Le duo mène en parallèle le projet happy hardcore Tweekacore et le trio The Elite avec Coone et Hard Driver.", en: "Da Tweekaz are a Norwegian hardstyle duo made up of Kenth Kvien and Marcus Nordli, active since the late 2000s and based in Belgium since 2012 to be closer to the Benelux festival circuit. Their records come out on Dirty Workz, starting with the album Time 2 Shine in 2012. Alongside it they run the happy hardcore project Tweekacore and the trio The Elite with Coone and Hard Driver." }, origin: "Norvège", since: 2007, labels: ["Dirty Workz"], sources: ["https://nl.wikipedia.org/wiki/Da_Tweekaz", "https://no.wikipedia.org/wiki/Da_Tweekaz"], photo: { file: "da-tweekaz.webp", author: "Stefan Brending (2eight)", license: "CC BY-SA 3.0", page: "https://commons.wikimedia.org/wiki/File:2016_Open_Beatz_-_Da_Tweekaz_-_by_2eight_-DSC_4580.jpg" } }, // Da Tweekaz
  "dasha-rush": { slug: "dasha-rush", bio: { fr: "Dasha Rush est une productrice et DJ née en Russie, de nationalité française et installée à Berlin. Sa techno se déploie sur plusieurs plans, du club au terrain expérimental et ambient — l'album Sleepstep en est l'illustration la plus connue — et s'accompagne de collaborations avec des plasticiens et des danseurs. Elle dirige son label Fullpanda Records et sa sous-division plus exploratoire, Hunger to Create.", en: "Dasha Rush is a Russian-born, French-national producer and DJ based in Berlin. Her techno works on several levels at once, from the club to experimental and ambient territory — the album Sleepstep being the best-known example — alongside collaborations with visual artists and dancers. She runs the label Fullpanda Records and its more exploratory sub-label, Hunger to Create." }, origin: "Russie, installée à Berlin", labels: ["Fullpanda Records", "Hunger to Create"], sources: ["https://grayarea.co/artists/dasha-rush"] }, // Dasha Rush
  "dax-j": { slug: "dax-j", bio: { fr: "Dax J, de son vrai nom Dax Heddon, est un DJ et producteur de techno né à Londres et installé à Berlin. Il commence à mixer à quinze ans sur les radios pirates londoniennes et publie ses premiers vinyles en 2005 dans la jungle et la drum & bass, avant de basculer vers la techno. Il fonde le label Monnom Black en 2013 et tient son propre studio de mastering à Berlin.", en: "Dax J, real name Dax Heddon, is a techno DJ and producer born in London and based in Berlin. He started DJing at fifteen on London pirate radio and put out his first vinyl in 2005 in jungle and drum & bass, before moving to techno. He founded the Monnom Black label in 2013 and runs his own mastering studio in Berlin." }, origin: "Londres, Royaume-Uni / Berlin, Allemagne", since: 2005, labels: ["Monnom Black"], sources: ["https://www.amsterdam-dance-event.nl/en/artists-speakers/dax-j/20348/", "https://www.discogs.com/artist/819825"] }, // Dax J
  "deborah-de-luca": { slug: "deborah-de-luca", bio: { fr: "Deborah De Luca, née le 23 juillet 1980 à Naples, est une DJ et productrice italienne. Elle a grandi aux Vele di Scampia, dans la périphérie napolitaine, et joue une techno dure et minimale. Elle a créé son propre label, Sola_Mente Records, pour sortir sa musique de manière indépendante, et a publié les albums Ten (2018) et She Sleeps (2020). Son set filmé par Cercle au château de Chambord en 2017 dépasse les 25 millions de vues sur YouTube.", en: "Deborah De Luca, born 23 July 1980 in Naples, is an Italian DJ and producer. She grew up in the Vele di Scampia on the city's outskirts and plays hard, minimal techno. She set up her own label, Sola_Mente Records, to release her music independently, and put out the albums Ten (2018) and She Sleeps (2020). Her set filmed by Cercle at the Château de Chambord in 2017 has passed 25 million views on YouTube." }, origin: "Naples, Italie", since: 2012, labels: ["Sola_Mente Records"], sources: ["https://es.wikipedia.org/wiki/Deborah_De_Luca"], photo: { file: "deborah-de-luca.webp", author: "Denis Apel", license: "CC BY-SA 4.0", page: "https://commons.wikimedia.org/wiki/File:Sterne_und_Bass-Feb_2017-Deborah_de_Luca-Flyingpixel-8380.jpg" } }, // Deborah De Luca
  "dimension": { slug: "dimension", bio: { fr: "Dimension, de son vrai nom Robert Etheridge, est un producteur et DJ anglais né en 1991 à Londres. Il produit de la drum and bass et a sorti son premier single, « Delight », en 2012 avant d'être signé sur MTA Records par Chase & Status en 2014. Son single « Desire », avec Sub Focus, est entré au UK Singles Chart en 2018 et a été certifié disque de platine au Royaume-Uni. Son premier album, « Organ », est sorti en mars 2021 et s'est classé numéro un des ventes dance britanniques.", en: "Dimension, real name Robert Etheridge, is an English producer and DJ born in London in 1991. He makes drum and bass and released his first single, \"Delight\", in 2012 before being signed to MTA Records by Chase & Status in 2014. His single \"Desire\" with Sub Focus charted on the UK Singles Chart in 2018 and went platinum in the UK. His debut album \"Organ\" came out in March 2021 and entered the UK Official Dance Chart at number one." }, origin: "Londres, Royaume-Uni", since: 2012, labels: ["MTA Records"], sources: ["https://en.wikipedia.org/wiki/Dimension_(musician)"] }, // Dimension
  "disclosure": { slug: "disclosure", bio: { fr: "Duo britannique formé en 2010 à Reigate, dans le Surrey, par les frères Guy et Howard Lawrence. Leur house traversée de UK garage et de 2-step a percé avec l'album Settle (2013), numéro un au Royaume-Uni, et le single « Latch » chanté par Sam Smith. Ont suivi Caracal (2015), Energy (2020) et Alchemy (2023).", en: "British duo formed in 2010 in Reigate, Surrey, by brothers Guy and Howard Lawrence. Their house music, shot through with UK garage and 2-step, broke through with the album Settle (2013), a UK number one, and the single \"Latch\" featuring Sam Smith. Caracal (2015), Energy (2020) and Alchemy (2023) followed." }, origin: "Reigate, Royaume-Uni", since: 2010, labels: ["PMR Records", "Island Records"], sources: ["https://en.wikipedia.org/wiki/Disclosure_(band)"], photo: { file: "disclosure.webp", author: "Andresojeda713", license: "CC BY-SA 4.0", page: "https://commons.wikimedia.org/wiki/File:Disclosure_en_Concierto_(2016).jpg" } }, // Disclosure
  "dj-gigola": { slug: "dj-gigola", bio: { fr: "DJ Gigola est une DJ et productrice berlinoise, membre du collectif et label Live From Earth. Elle a terminé des études de médecine avant de vivre de la musique, et revendique un jeu sans frontières de genre : trance techno des années 2000, tech house et son high energy d'aujourd'hui, plus quelques détours par le rap et la pop. Son EP Bigroom Sensual (Live From Earth, 2024) met en scène cette réconciliation entre générations de dancefloor.", en: "DJ Gigola is a Berlin DJ and producer and a member of the Live From Earth collective and label. She finished a medical degree before turning to music full time, and plays deliberately across genre lines: early-2000s trance techno, tech house and today's high-energy sound, with detours through rap and pop. Her EP Bigroom Sensual (Live From Earth, 2024) frames that as a reconciliation between dancefloor generations." }, origin: "Berlin, Allemagne", labels: ["Live From Earth"], sources: ["https://www.exitfest.org/en/dj-gigola-the-creative-mind-of-the-new-techno-generation-from-berlin", "https://livefromearth.bandcamp.com/album/bigroom-sensual"] }, // DJ Gigola
  "dj-snake": { slug: "dj-snake", bio: { fr: "William Grigahcine, né à Paris en 1986 et d'origine algérienne, produit depuis 2009 un electro house croisé de trap et de moombahton. « Turn Down for What » avec Lil Jon (2013), « Lean On » avec Major Lazer et MØ (2015) puis « Taki Taki » (2018) l'ont porté au premier plan mondial. Il a publié les albums Encore (2016), Carte Blanche (2019) et Nomad (2025).", en: "William Grigahcine, born in Paris in 1986 and of Algerian descent, has been producing electro house crossed with trap and moombahton since 2009. \"Turn Down for What\" with Lil Jon (2013), \"Lean On\" with Major Lazer and MØ (2015) and \"Taki Taki\" (2018) took him worldwide. He has released the albums Encore (2016), Carte Blanche (2019) and Nomad (2025)." }, origin: "Paris, France", since: 2009, labels: ["Interscope Records", "Première Classe"], sources: ["https://fr.wikipedia.org/wiki/DJ_Snake"], photo: { file: "dj-snake.webp", author: "Arno Partissimo", license: "CC BY-SA 4.0", page: "https://commons.wikimedia.org/wiki/File:DJS-Presskit05_(cropped).jpg" } }, // DJ Snake
  "donato-dozzy": { slug: "donato-dozzy", bio: { fr: "Donato Dozzy, de son vrai nom Donato Scaramuzzi, est un DJ et producteur italien né à Rome, actif derrière les platines depuis le début des années 1980. Il s'est fait connaître pour une techno hypnotique et lentement évolutive, forgée lors de ses résidences au Brancaleone de Rome puis au Panorama Bar de Berlin, où il tenait les after de 2004 à 2006. Il a cofondé le label Aquaplano avec Nuel en 2008, puis Spazio Disponibile avec Neel, et publié son premier album solo, « K », sur Further Records en 2010. Son projet Voices from the Lake, avec Neel, a sorti en 2012 un album homonyme salué par la critique.", en: "Donato Dozzy, born Donato Scaramuzzi, is an Italian DJ and producer from Rome who has been playing records since the early 1980s. He is known for a hypnotic, slowly unfolding strain of techno shaped by residencies at Rome's Brancaleone and Berlin's Panorama Bar, where he handled the after-hours from 2004 to 2006. He co-founded the Aquaplano label with Nuel in 2008 and later Spazio Disponibile with Neel, and released his first solo album, \"K\", on Further Records in 2010. His Voices from the Lake project with Neel put out a widely praised self-titled album in 2012." }, origin: "Rome, Italie", since: 1983, labels: ["Aquaplano", "Spazio Disponibile", "Further Records"], sources: ["https://www.innerspaces.it/artists/donato-dozzy/"] }, // Donato Dozzy
  "dr-donk": { slug: "dr-donk", bio: { fr: "Dr Donk est un DJ et producteur allemand basé à Cologne, actif dans les registres uptempo, rawstyle et hardcore. Il a construit son personnage autour d'un décor de clinique médicale, jusqu'au nom d'artiste et au titre de ses sets. Ses morceaux paraissent sur les labels du circuit hard dance — Greazy Recordz, Snakepit Music, Defqon.1 Records, Q-dance Records ou Basscon — et il joue au Bootshaus de Cologne comme à Parookaville.", en: "Dr Donk is a German DJ and producer based in Cologne, working in the uptempo, rawstyle and hardcore end of hard dance. He built his persona around a medical-clinic conceit, from the stage name down to the framing of his sets. His tracks come out on hard dance labels including Greazy Recordz, Snakepit Music, Defqon.1 Records, Q-dance Records and Basscon, and he plays Cologne's Bootshaus as well as Parookaville." }, origin: "Cologne, Allemagne", labels: ["Greazy Recordz", "Snakepit Music", "Q-dance Records"], sources: ["https://hardstyle.com/en/artists/dr-donk", "https://www.parookaville.com/de/artist/dr-donk"] }, // Dr Donk
  "dr-peacock": { slug: "dr-peacock", bio: { fr: "Stefan Dekker, néerlandais originaire de Limmen, produit de la frenchcore depuis 2010. Il a fondé Peacock Records, puis Frenchcore Worldwide en 2017 et Euphoric Frenchcore Records en 2019, et signé avec Angerfist l'album The Deadfaced Dimension (2013). Il a joué au Defqon.1, au Thunderdome et au Qlimax, où son set de 2019 était le premier set frenchcore de l'histoire de l'événement.", en: "Stefan Dekker, a Dutch producer from Limmen, has been making frenchcore since 2010. He founded Peacock Records, then Frenchcore Worldwide in 2017 and Euphoric Frenchcore Records in 2019, and made the album The Deadfaced Dimension (2013) with Angerfist. He has played Defqon.1, Thunderdome and Qlimax, where his 2019 set was the event's first ever frenchcore set." }, origin: "Limmen, Pays-Bas", since: 2010, labels: ["Peacock Records", "Frenchcore Worldwide"], sources: ["https://en.wikipedia.org/wiki/Dr._Peacock"], photo: { file: "dr-peacock.webp", author: "Ss279", license: "CC BY-SA 4.0", page: "https://commons.wikimedia.org/wiki/File:Mayday_2019_Dr._Peacock_2.jpg" } }, // Dr. Peacock
  "dual-damage": { slug: "dual-damage", bio: { fr: "Dual Damage est un duo néerlandais de raw hardstyle formé par Thijs Rooijakkers et Jesper Habraken. Leur son repose sur des kicks lourds, des breaks énergiques et des mélodies planantes, avec la « PVC kick » comme signature. Ils publient notamment sur Ravage Records, avec des titres comme « Gold Sky », « Into The Wild » ou « Built 2 Break ».", en: "Dual Damage are a Dutch raw hardstyle duo made up of Thijs Rooijakkers and Jesper Habraken. Their sound rests on heavy kicks, energetic breaks and uplifting melodies, with the \"PVC kick\" as their signature. They release notably on Ravage Records, with tracks such as \"Gold Sky\", \"Into The Wild\" and \"Built 2 Break\"." }, origin: "Pays-Bas", labels: ["Ravage Records"], sources: ["https://hardstyle.com/en/artists/dual-damage", "https://www.discogs.com/artist/12581201"] }, // Dual Damage
  "dyen": { slug: "dyen", bio: { fr: "Producteur et DJ néerlandais de Rotterdam, il commence la production à dix-sept ans et sort ses premiers disques à partir de 2017. Il décrit sa musique comme de la « neorave » ou de la hard techno old school : des kicks hérités du gabber des années 1990 croisés avec des synthés trance agressifs. Il a publié sur Possession, EXHALE et Filth On Acid.", en: "Dutch producer and DJ from Rotterdam, he started producing at seventeen and put out his first records from 2017 on. He calls his music \"neorave\" or old-school hard techno: kicks inherited from 1990s gabber crossed with aggressive trance synths. He has released on Possession, EXHALE and Filth On Acid." }, origin: "Rotterdam, Pays-Bas", since: 2017, labels: ["Possession", "EXHALE", "Filth On Acid"], sources: ["https://reckless-rec.com/artists/dyen/", "https://dyen.bandcamp.com/"] }, // DYEN
  "ellen-allien": { slug: "ellen-allien", bio: { fr: "Ellen Fraatz, née à Berlin-Ouest, mixe dans les clubs de la ville depuis 1992 et façonne une techno expérimentale proche de l'IDM, qu'elle chante parfois en allemand et en anglais. Elle a fondé le label BPitch Control en 1999 et publié notamment Berlinette (2003), Thrills (2005) et Orchestra of Bubbles (2006) avec Apparat.", en: "Ellen Fraatz, born in West Berlin, has been DJing in the city's clubs since 1992 and shapes an experimental techno close to IDM, over which she sometimes sings in German and English. She founded the BPitch Control label in 1999 and released Berlinette (2003), Thrills (2005) and Orchestra of Bubbles (2006) with Apparat." }, origin: "Berlin, Allemagne", since: 1992, labels: ["BPitch Control"], sources: ["https://en.wikipedia.org/wiki/Ellen_Allien"], photo: { file: "ellen-allien.webp", author: "Ventura Mendoza", license: "CC BY 2.0", page: "https://commons.wikimedia.org/wiki/File:Ellen_Allien_(MAGMA_2006,_Tenerife).jpg" } }, // Ellen Allien
  "enrico-sangiuliano": { slug: "enrico-sangiuliano", bio: { fr: "Producteur et DJ italien originaire d'Émilie-Romagne, Enrico Sangiuliano perce en 2015 avec son remix de « Can You Hear Me » de DJ Boris, puis avec l'EP « Moon Rocks » qui fait de lui l'artiste techno le plus vendu sur Beatport en 2016. Il publie en juin 2018 son premier album, « Biomorph », sur le label Drumcode d'Adam Beyer. En 2022, il lance NINETOZERO, un label conçu pour ne compter que dix sorties avant de s'arrêter, accompagné de la série de soirées SOLO en all-night-long.", en: "An Italian producer and DJ from the Emilia region, Enrico Sangiuliano broke through in 2015 with his remix of DJ Boris's \"Can You Hear Me\", then with the \"Moon Rocks\" EP that made him Beatport's best-selling techno artist of 2016. In June 2018 he released his first album, \"Biomorph\", on Adam Beyer's Drumcode label. In 2022 he launched NINETOZERO, a label designed to run for exactly ten releases before ending, paired with his SOLO all-night-long party series." }, origin: "Émilie-Romagne, Italie", labels: ["Drumcode", "NINETOZERO"], sources: ["https://www.drumcode.se/artists/enrico-sangiuliano", "https://electronicgroove.com/interview-enrico-sangiuliano-2022/"] }, // Enrico Sangiuliano
  "enzo-siragusa": { slug: "enzo-siragusa", bio: { fr: "Enzo Siragusa est un DJ et producteur britannique né en 1978 de parents siciliens installés à Maidenhead, dans le Berkshire. Passé par le jungle des raves britanniques du début des années 1990, il bascule vers la house à 16 ans. Fin 2008, il lance FUSE, une soirée dominicale au 93 Feet East dans l'est de Londres, devenue une marque internationale doublée d'un label FUSE et de son pendant plus profond, INFUSE. Son son, house dubbée à basses lourdes traversée de références jungle, garage et techno, est surnommé « Fusic » par son public.", en: "Enzo Siragusa is a British DJ and producer born in 1978 to Sicilian parents settled in Maidenhead, Berkshire. A junglist raised on early-1990s UK rave culture, he switched to house at 16. In late 2008 he launched FUSE, a Sunday party at 93 Feet East in East London that grew into an international brand with its own FUSE label and a deeper sister imprint, INFUSE. His sound — dubbed-out house with heavy sub-bass, threaded with jungle, garage and techno — has been nicknamed \"Fusic\" by his audience." }, origin: "Maidenhead, Royaume-Uni", since: 2008, labels: ["FUSE", "INFUSE"], sources: ["https://djmag.com/longreads/enzo-siragusa-lighting-fuse"] }, // Enzo Siragusa
  "eric-prydz": { slug: "eric-prydz", bio: { fr: "Producteur suédois né en 1976 à Täby, près de Stockholm, il répartit sa production entre la house progressive signée Pryda et la techno plus dure de son alias Cirez D. « Call on Me » (2004) est resté cinq semaines en tête des ventes britanniques, avant « Pjanoo » (2008) et l'album Opus (2016). Ses spectacles EPIC et HOLO reposent sur des dispositifs holographiques de grande échelle.", en: "Swedish producer born in 1976 in Täby, near Stockholm, splitting his output between the progressive house he signs as Pryda and the harder techno of his Cirez D alias. \"Call on Me\" (2004) spent five weeks at number one in the UK, followed by \"Pjanoo\" (2008) and the album Opus (2016). His EPIC and HOLO shows are built around large-scale holographic staging." }, origin: "Täby, Suède", since: 2004, labels: ["Pryda", "Mouseville Records"], sources: ["https://en.wikipedia.org/wiki/Eric_Prydz"], photo: { file: "eric-prydz.webp", author: "Haydn Curtis", license: "CC BY 2.0", page: "https://commons.wikimedia.org/wiki/File:Eric_Prydz_at_Glastonbury_2009.jpg" } }, // Eric Prydz
  "fantasm": { slug: "fantasm", bio: { fr: "Kenzo Meservey, originaire de Los Angeles et installé à Lyon, s'est fait connaître en 2023 dans la techno industrielle et rave. Ses morceaux « Requiem Psycho » avec Hades, « NFWU » avec Exproz et « Red Spider Lilly » l'ont porté jusqu'à la 93e place du Top 100 DJs de DJ Mag en 2025, où il entrait pour la première fois. Il est un habitué des soirées Verknipt.", en: "Kenzo Meservey, from Los Angeles and based in Lyon, made his mark in 2023 in industrial and rave techno. His tracks \"Requiem Psycho\" with Hades, \"NFWU\" with Exproz and \"Red Spider Lilly\" carried him to number 93 in DJ Mag's Top 100 DJs in 2025, his first appearance on the list. He is a regular at Verknipt parties." }, origin: "Los Angeles, États-Unis", since: 2023, sources: ["https://djmag.com/top100djs/2025/93/fantasm", "https://mixmagnl.com/read/fantasm-artists"] }, // Fantasm
  "fatboy-slim": { slug: "fatboy-slim", bio: { fr: "Norman Cook, né en 1963 à Bromley et installé à Brighton, adopte l'alias Fatboy Slim en 1995 pour un big beat bâti sur des breakbeats hip-hop et l'énergie de l'acid house. L'album You've Come a Long Way, Baby (1998) et les singles « The Rockafeller Skank », « Praise You » et « Right Here, Right Now » l'ont fait sortir des clubs. Il enregistre principalement pour Skint Records.", en: "Norman Cook, born in Bromley in 1963 and based in Brighton, took the Fatboy Slim alias in 1995 for a big beat built on hip-hop breakbeats and the energy of acid house. The album You've Come a Long Way, Baby (1998) and the singles \"The Rockafeller Skank\", \"Praise You\" and \"Right Here, Right Now\" carried him well beyond the clubs. He records mainly for Skint Records." }, origin: "Bromley, Royaume-Uni", since: 1995, labels: ["Skint Records", "Southern Fried Records"], sources: ["https://en.wikipedia.org/wiki/Fatboy_Slim"], photo: { file: "fatboy-slim.webp", author: "Tadeáš Kirschner", license: "CC BY 4.0", page: "https://commons.wikimedia.org/wiki/File:Fatboy_Slim,_Iris_Festival_2025.jpg" } }, // Fatboy Slim
  "floating-points": { slug: "floating-points", bio: { fr: "Sam Shepherd, originaire de Manchester, mène en parallèle une carrière électronique et un doctorat en neurosciences obtenu à University College London. Ses albums Elaenia (2015), Crush (2019) et Cascade (2024) croisent house, jazz et écriture orchestrale, et il dirige le label Pluto Records. Promises (2021), enregistré avec Pharoah Sanders et le London Symphony Orchestra, a été nommé au Mercury Prize.", en: "Sam Shepherd, from Manchester, runs an electronic career alongside a PhD in neuroscience taken at University College London. His albums Elaenia (2015), Crush (2019) and Cascade (2024) cross house, jazz and orchestral writing, and he runs the Pluto Records label. Promises (2021), recorded with Pharoah Sanders and the London Symphony Orchestra, was nominated for the Mercury Prize." }, origin: "Manchester, Royaume-Uni", since: 2009, labels: ["Pluto Records"], sources: ["https://en.wikipedia.org/wiki/Floating_Points"], photo: { file: "floating-points.webp", author: "Fred von Lohmann", license: "CC0", page: "https://commons.wikimedia.org/wiki/File:Floating_Points_at_Coachella_2017_(cropped).jpg" } }, // Floating Points
  "folamour": { slug: "folamour", bio: { fr: "Folamour, de son vrai nom Bruno Boumendil, est un DJ et producteur français, fondateur du label FHUO Records. Formé à la guitare, à la batterie et aux percussions, il se fait remarquer avec l'EP Deeply Rooted Vibes vers 2014, puis avec les albums Umami en 2017, Ordinary Drugs en 2019 et The Journey en 2021, où il délaisse les samples pour des instruments joués et des textes originaux. Son répertoire mêle house, disco et future jazz.", en: "Folamour, real name Bruno Boumendil, is a French DJ and producer and the founder of FHUO Records. Trained on guitar, drums and percussion, he broke through with the EP Deeply Rooted Vibes around 2014, then with the albums Umami in 2017, Ordinary Drugs in 2019 and The Journey in 2021, on which he set samples aside for live instruments and original lyrics. His catalogue blends house, disco and future jazz." }, origin: "France", since: 2014, labels: ["FHUO Records"], sources: ["https://fr.wikipedia.org/wiki/Folamour_(musicien)", "https://en.wikipedia.org/wiki/Folamour"], photo: { file: "folamour.webp", author: "Originalcat", license: "CC BY-SA 4.0", page: "https://commons.wikimedia.org/wiki/File:Folamour_at_StrafWerk_Amsterdam_2023.jpg" } }, // Folamour
  "four-tet": { slug: "four-tet", bio: { fr: "Kieran Hebden, né en 1977 à Putney (Londres), enregistre sous le nom de Four Tet une électronique bricolée à partir de samples, d'abord au sein du groupe post-rock Fridge. Ses albums « Rounds » (2003) et « There Is Love in You » (2010) l'ont établi en solo, et il a enregistré plusieurs disques d'improvisation avec le batteur de jazz Steve Reid ainsi que des collaborations avec Burial et Thom Yorke. Il a aussi produit Omar Souleyman et arrangé l'album « Sound Ancestors » de Madlib en 2021.", en: "Born in Putney, London in 1977, Kieran Hebden records as Four Tet, making sample-built electronic music, first within the post-rock band Fridge. His albums \"Rounds\" (2003) and \"There Is Love in You\" (2010) established him as a solo artist, and he cut several improvised records with jazz drummer Steve Reid as well as collaborations with Burial and Thom Yorke. He has also produced Omar Souleyman and arranged Madlib's 2021 album \"Sound Ancestors\"." }, origin: "Londres, Angleterre", sources: ["https://en.wikipedia.org/wiki/Four_Tet"], photo: { file: "four-tet.webp", author: "Chris Pimlott", license: "CC BY-SA 3.0", page: "https://commons.wikimedia.org/wiki/File:Four_Tet_2004-04-04_(cropped).jpg" } }, // Four Tet
  "francesco-del-garda": { slug: "francesco-del-garda", bio: { fr: "Francesco Del Garda est un DJ italien qui joue exclusivement en vinyle, format auquel il est resté fidèle depuis ses seize ans. Ses sets circulent entre house, electro, garage, techno et minimale, et reposent sur des disques rares dénichés au fil des bacs. En 2017, il a lancé son label Timeless pour publier de jeunes producteurs au style marqué. Il joue aussi bien en cave qu'en plein air, notamment au Dimensions Festival.", en: "Francesco Del Garda is an Italian DJ who plays vinyl only, a format he has stuck with since he was sixteen. His sets move between house, electro, garage, techno and minimal, built on rare records turned up through years of digging. In 2017 he launched his label Timeless to put out young producers with a distinctive style. He plays basements and open-air festivals alike, including Dimensions Festival." }, origin: "Italie", labels: ["Timeless"], sources: ["https://www.horstartsandmusic.com/programme/francesco-del-garda", "https://www.paradisecity.be/en/bands/francesco-del-garda"] }, // Francesco Del Garda
  "goldie": { slug: "goldie", bio: { fr: "Clifford Joseph Price, né en 1965 en Angleterre, se fait d'abord connaître comme graffeur avant de devenir une figure de la jungle et de la drum and bass britanniques des années 1990. Il publie des disques sous les noms Rufige Kru et Metalheads et cofonde le label Metalheadz. Son album « Timeless » entre en 1995 à la septième place des charts britanniques. Il est aussi acteur, notamment dans « Le monde ne suffit pas » et « Snatch ».", en: "Born in England in 1965, Clifford Joseph Price first made his name as a graffiti artist before becoming a central figure in 1990s UK jungle and drum and bass. He released records as Rufige Kru and Metalheads and co-founded the Metalheadz label. His album \"Timeless\" entered the UK charts at number seven in 1995. He also acts, notably in \"The World Is Not Enough\" and \"Snatch\"." }, origin: "Angleterre", labels: ["Metalheadz"], sources: ["https://en.wikipedia.org/wiki/Goldie"] }, // Goldie
  "gusgus": { slug: "gusgus", bio: { fr: "GusGus est un groupe islandais de musique électronique fondé à Reykjavík en 1995, au départ comme un collectif de cinéma et de théâtre. Sa production navigue entre techno, house, downtempo et ambient, du premier album Polydistortion (1997) à Arabian Horse (2011), son disque le mieux classé. Le groupe a publié chez 4AD puis Kompakt et son propre label Oroom, et a remixé Björk, Depeche Mode et Sigur Rós.", en: "GusGus are an Icelandic electronic group founded in Reykjavík in 1995, initially as a film and acting collective. Their output moves between techno, house, downtempo and ambient, from the first album Polydistortion (1997) to Arabian Horse (2011), their highest-charting record. They have released on 4AD, then Kompakt and their own Oroom label, and have remixed Björk, Depeche Mode and Sigur Rós." }, origin: "Reykjavík, Islande", since: 1995, labels: ["Oroom", "Kompakt", "4AD"], sources: ["https://en.wikipedia.org/wiki/GusGus"] }, // GusGus
  "hannah-laing": { slug: "hannah-laing", bio: { fr: "DJ et productrice écossaise née en 1994 à Dundee, Hannah Laing joue une trance, une techno et une hard house à haute énergie. Elle a exercé dix ans comme assistante dentaire avant de passer à la musique à plein temps après un set remarqué à Creamfields en 2022 ; elle a été nommée aux DJ Mag Best of Britain en 2023 et a réalisé un Essential Mix de deux heures sur BBC Radio 1. Son label et marque d'événements Doof a lancé en juillet 2025 le festival Doof in the Park à Camperdown Park, à Dundee, devant environ 15 000 personnes.", en: "A Scottish DJ and producer born in Dundee in 1994, Hannah Laing plays high-energy trance, techno and hard house. She worked as a dental nurse for ten years before turning to music full time after a well-received Creamfields set in 2022; she was nominated for a DJ Mag Best of Britain award in 2023 and recorded a two-hour Essential Mix for BBC Radio 1. Her label and events brand Doof launched the Doof in the Park festival at Camperdown Park in Dundee in July 2025, drawing some 15,000 people." }, origin: "Dundee, Écosse", labels: ["Doof"], sources: ["https://en.wikipedia.org/wiki/Hannah_Laing", "https://en.wikipedia.org/wiki/Doof_in_the_Park"], photo: { file: "hannah-laing.webp", author: "KeyKing666", license: "CC BY-SA 4.0", page: "https://commons.wikimedia.org/wiki/File:Hannah_Laing_2026.png" } }, // Hannah Laing
  "helena-hauff": { slug: "helena-hauff", bio: { fr: "DJ et productrice hambourgeoise, elle compose sur du matériel exclusivement analogique une électro acide traversée d'EBM et d'industriel. Elle a tenu la soirée « Birds and Other Instruments » au Golden Pudel Club, sorti son premier EP en 2013, puis les albums Discreet Desires (2015) et Qualm (2018) chez Ninja Tune. Elle dirige le label Return to Disorder.", en: "A DJ and producer from Hamburg, she works on strictly analogue gear, building acid-tinged electro shot through with EBM and industrial. She ran the \"Birds and Other Instruments\" night at the Golden Pudel Club, released her first EP in 2013, then the albums Discreet Desires (2015) and Qualm (2018) on Ninja Tune. She runs the Return to Disorder label." }, origin: "Hambourg, Allemagne", since: 2013, labels: ["Return to Disorder", "Ninja Tune"], sources: ["https://en.wikipedia.org/wiki/Helena_Hauff"], photo: { file: "helena-hauff.webp", author: "deepskyobject from Saint Petersburg, Russia", license: "CC BY-SA 2.0", page: "https://commons.wikimedia.org/wiki/File:Helena_Hauff_@_Primavera_Sound_Festival,_Barcelona,_02.06.2016_(36682200586)_(cropped).jpg" } }, // Helena Hauff
  "hilight-tribe": { slug: "hilight-tribe", bio: { fr: "Hilight Tribe est un groupe français qui joue une « natural trance » : une transe rejouée en direct par des musiciens, sans ordinateur, à la percussion, à la guitare, à la basse, à la batterie, au didgeridoo et au sitar. Le collectif nourrit son répertoire d'instruments et de rythmes rapportés du Mali, du Sénégal, du Burkina Faso, d'Inde et du Brésil. Son morceau « Free Tibet » a été repris par Vini Vici, et le groupe a signé « Great Spirit » avec Vini Vici et Armin van Buuren en 2017.", en: "Hilight Tribe are a French band playing what they call natural trance: trance performed live by musicians rather than computers, on percussion, guitar, bass, drums, didgeridoo and sitar. The group builds its repertoire from instruments and rhythms brought back from Mali, Senegal, Burkina Faso, India and Brazil. Their track \"Free Tibet\" was reworked by Vini Vici, and in 2017 the band recorded \"Great Spirit\" with Vini Vici and Armin van Buuren." }, origin: "France", sources: ["https://www.tranceinfrance.com/hilight-tribe/", "https://ravefeed.com/2017/08/24/interview-hilight-tribe/"] }, // Hilight Tribe
  "holy-priest": { slug: "holy-priest", bio: { fr: "Holy Priest est un producteur et DJ allemand installé à Oberhausen, en Rhénanie-du-Nord-Westphalie, où il tient son studio. Il joue masqué et garde son identité secrète, sur une hard techno industrielle faite de kicks saturés, de basses distordues et de lignes acid. Il publie des EP depuis 2020, chez Revised Records, CodeX Recordings et Chlore Records, dont une série aux titres latins (Unus, Duo, Tres) et le morceau « Rave Penetrator ».", en: "Holy Priest is a German producer and DJ based in Oberhausen, North Rhine-Westphalia, where he keeps his studio. He performs masked and keeps his identity private, playing industrial-edged hard techno built on saturated kicks, distorted bass and acid lines. He has been putting out EPs since 2020 on Revised Records, CodeX Recordings and Chlore Records, including a run of Latin-titled releases (Unus, Duo, Tres) and the track \"Rave Penetrator\"." }, origin: "Oberhausen, Allemagne", since: 2020, labels: ["Revised Records", "CodeX Recordings", "Chlore Records"], sources: ["https://fr.wikipedia.org/wiki/Holy_Priest"] }, // Holy Priest
  "honey-dijon": { slug: "honey-dijon", bio: { fr: "Honey Redmond, née en 1968 dans le South Side de Chicago, mixe sous le nom de Honey Dijon et vit entre New York et Berlin. Formée dans le sillage de DJ comme Derrick Carter et Mark Farina, elle commence à mixer dans les années 1990 et à produire vers 2000, entre house et techno. Son premier album, « The Best of Both Worlds », paraît en 2017 ; elle travaille aussi régulièrement avec la mode, notamment Louis Vuitton et Dior.", en: "Born in 1968 on Chicago's South Side, Honey Redmond DJs as Honey Dijon and is based between New York City and Berlin. Mentored by DJs such as Derrick Carter and Mark Farina, she began DJing in the 1990s and producing around 2000, working between house and techno. Her debut album \"The Best of Both Worlds\" came out in 2017, and she works regularly with fashion houses including Louis Vuitton and Dior." }, origin: "Chicago, États-Unis", sources: ["https://en.wikipedia.org/wiki/Honey_Dijon"], photo: { file: "honey-dijon.webp", author: "LOVE Magazine", license: "CC BY 3.0", page: "https://commons.wikimedia.org/wiki/File:Honey_Dijon_on_the_LOVE_18_set.jpg" } }, // Honey Dijon
  "hybrid-minds": { slug: "hybrid-minds", bio: { fr: "Hybrid Minds est un duo britannique de drum and bass composé de Josh White et Matt Lowe, actif depuis le début des années 2010. Ils travaillent le versant liquide du genre : basses roulantes, nappes atmosphériques et voix invitées, avec des collaborations récurrentes avec les chanteuses Charlotte Haining et Alexa Harley. Leur premier album, « Mountains », est paru en 2013. Ils publient l'essentiel de leur musique sur leur propre label, Hybrid Music.", en: "Hybrid Minds are a British drum and bass duo made up of Josh White and Matt Lowe, active since the early 2010s. They work the liquid end of the genre: rolling basslines, atmospheric pads and guest vocals, with recurring collaborations with singers Charlotte Haining and Alexa Harley. Their debut album \"Mountains\" came out in 2013. They release most of their music on their own label, Hybrid Music." }, origin: "Royaume-Uni", since: 2012, labels: ["Hybrid Music"], sources: ["https://relentlessbeats.com/2025/04/artist-spotlight-who-is-hybrid-minds/"] }, // Hybrid Minds
  "hysta": { slug: "hysta", bio: { fr: "Thaïs Morel, née en 1998 à La Gacilly dans le Morbihan, mixe sous le nom d'Hysta un hardcore mainstream hérité des free parties bretonnes, où elle a commencé sur vinyle à 16 ans. Elle a sorti des titres sur Masters of Hardcore, The Third Movement et Q-dance Music, et est devenue en 2023 la première DJ française à jouer sur la scène principale du Thunderdome. En septembre 2025, elle a donné un set hardcore d'une heure au deuxième étage de la tour Eiffel.", en: "Born in 1998 in La Gacilly, Brittany, Thaïs Morel DJs as Hysta, playing mainstream hardcore rooted in the Breton free-party scene where she started out on vinyl at sixteen. She has released on Masters of Hardcore, The Third Movement and Q-dance Music, and in 2023 became the first French female DJ to play Thunderdome's main stage. In September 2025 she performed a one-hour hardcore set on the second floor of the Eiffel Tower." }, origin: "La Gacilly, Morbihan, France", since: 2014, labels: ["Masters of Hardcore", "The Third Movement", "Q-dance Music"], sources: ["https://fr.wikipedia.org/wiki/Hysta"], photo: { file: "hysta.webp", author: "Philcotof", license: "CC BY-SA 4.0", page: "https://commons.wikimedia.org/wiki/File:Philcotof_dj_Hysta_DSC00001_attribution_AUTEUR_OBLIGATOIRE.jpg" } }, // Hysta
  "i-hate-models": { slug: "i-hate-models", bio: { fr: "I Hate Models, de son vrai nom Guillaume Labadie, né le 8 juin 1995, est un producteur et DJ français de techno, qui a grandi dans le sud de la France. Il débute en 2015 et publie son premier EP, Warehouse Memories, sur le label ARTS en 2016, avant de rejoindre le label londonien Perc Trax où paraît son premier album, L'Âge des métamorphoses, en juin 2019. Il apparaît quasi systématiquement masqué en public et limite ses échanges avec la presse.", en: "I Hate Models, real name Guillaume Labadie, born 8 June 1995, is a French techno producer and DJ who grew up in the south of France. He started in 2015 and released his first EP, Warehouse Memories, on the ARTS label in 2016, before joining London's Perc Trax, which issued his first album, L'Âge des métamorphoses, in June 2019. He almost always appears masked in public and keeps his press contact to a minimum." }, origin: "Sud de la France", since: 2015, labels: ["ARTS", "Perc Trax"], sources: ["https://fr.wikipedia.org/wiki/I_Hate_Models", "https://en.wikipedia.org/wiki/I_Hate_Models"] }, // I Hate Models
  "il-est-vilaine": { slug: "il-est-vilaine", bio: { fr: "Il Est Vilaine est un duo électronique parisien formé par Simon et Florent, épaulé sur le visuel par Apollo Thomas. Leur musique mêle house et techno à une acid-wave marquée par le post-punk et le krautrock. Leur premier EP, « Scandale », est paru en 2014 sur leur propre label Dialect Recordings, avant que Kill The DJ ne publie « Lumière noire » à l'été 2015.", en: "Il Est Vilaine are a Parisian electronic duo made up of Simon and Florent, with Apollo Thomas handling their visuals. Their music welds house and techno to an acid-wave streak marked by post-punk and krautrock. Their first EP, \"Scandale\", came out in 2014 on their own Dialect Recordings label, before Kill The DJ released \"Lumière noire\" in the summer of 2015." }, origin: "Paris, France", since: 2014, labels: ["Dialect Recordings", "Kill The DJ"], sources: ["https://vice.com/fr/article/rznbj3/il-est-vilaine-interview-2015"] }, // Il Est Vilaine
  "ilario-alicante": { slug: "ilario-alicante", bio: { fr: "Né en 1988 à Livourne, en Italie, Ilario Alicante commence comme résident du club Pachamama à Pise avant de rejoindre le collectif Cocoon de Sven Väth. Ses premiers titres marquants sont « Vacaciones en Chile » et « Living Near Africa », publié sur Cécille Records ; à vingt ans, il devient le plus jeune artiste programmé au Time Warp de Rotterdam. Il a fondé son propre label, Deep Moves Records, et sort régulièrement sur Drumcode.", en: "Born in Livorno, Italy in 1988, Ilario Alicante started out as a resident at the Pachamama club in Pisa before joining Sven Väth's Cocoon collective. His early standout tracks were \"Vacaciones en Chile\" and \"Living Near Africa\", released on Cécille Records; at twenty he became the youngest artist billed at Time Warp in Rotterdam. He founded his own label, Deep Moves Records, and releases regularly on Drumcode." }, origin: "Livourne, Italie", labels: ["Deep Moves Records", "Cocoon", "Drumcode"], sources: ["https://www.drumcode.se/artists/ilario-alicante"] }, // Ilario Alicante
  "interplanetary-criminal": { slug: "interplanetary-criminal", bio: { fr: "De son vrai nom Zachary Bruce, né en 1993 à Blackburn et installé à Manchester, il produit depuis 2012 un UK garage nerveux mêlé de speed garage et de breakbeat. Il a cofondé le label ATW Records avec Main Phase en 2019, et « B.O.T.A. (Baddest of Them All) », signé avec Eliza Rose en 2022, lui a valu deux semaines en tête des ventes britanniques et une nomination aux BRIT Awards.", en: "Real name Zachary Bruce, born in 1993 in Blackburn and based in Manchester, he has been producing edgy UK garage laced with speed garage and breakbeat since 2012. He co-founded the ATW Records label with Main Phase in 2019, and \"B.O.T.A. (Baddest of Them All)\", made with Eliza Rose in 2022, spent two weeks at number one in the UK and earned a BRIT Award nomination." }, origin: "Blackburn, Royaume-Uni", since: 2012, labels: ["ATW Records", "Shall Not Fade"], sources: ["https://en.wikipedia.org/wiki/Interplanetary_Criminal"] }, // Interplanetary Criminal
  "jamie-jones": { slug: "jamie-jones", bio: { fr: "Né en 1980 à Bontnewydd, au pays de Galles, il joue une house teintée de tech house et dirige le label Hot Creations. Il a lancé en 2012 la soirée Paradise, tenue huit saisons au DC10 d'Ibiza avant de rejoindre l'Amnesia en 2022, et fait partie du collectif Hot Natured, dont le single « Benediction » est entré au classement britannique en 2012.", en: "Born in 1980 in Bontnewydd, Wales, he plays house shaded with tech house and runs the Hot Creations label. In 2012 he launched the Paradise party, which ran eight seasons at DC10 in Ibiza before moving to Amnesia in 2022, and he is part of the Hot Natured collective, whose single \"Benediction\" charted in the UK in 2012." }, origin: "Bontnewydd, Pays de Galles", since: 2003, labels: ["Hot Creations"], sources: ["https://en.wikipedia.org/wiki/Jamie_Jones_(DJ)"] }, // Jamie Jones
  "jeff-mills": { slug: "jeff-mills", bio: { fr: "Jeff Mills, né le 18 juin 1963 à Détroit, est un DJ, producteur et compositeur américain, également connu sous le nom de « The Wizard ». À la fin des années 1980, il cofonde le collectif Underground Resistance avec Mike Banks et Robert Hood, avant de le quitter pour une carrière solo et de créer son label Axis Records en 1992. Il a reçu l'ordre des Arts et des Lettres en 2017.", en: "Jeff Mills, born 18 June 1963 in Detroit, is an American DJ, producer and composer, also known as \"The Wizard\". In the late 1980s he co-founded the Underground Resistance collective with Mike Banks and Robert Hood, then left for a solo career and started his label Axis Records in 1992. He was awarded the Ordre des Arts et des Lettres in 2017." }, origin: "Détroit, États-Unis", labels: ["Axis Records", "Underground Resistance"], sources: ["https://en.wikipedia.org/wiki/Jeff_Mills"], photo: { file: "jeff-mills.webp", author: "Angie Schwendemann", license: "CC BY-SA 2.0", page: "https://commons.wikimedia.org/wiki/File:Jeff_Mills_2.jpg" } }, // Jeff Mills
  "jennifer-cardini": { slug: "jennifer-cardini", bio: { fr: "Jennifer Cardini est une DJ et productrice française installée à Berlin, derrière les platines depuis une trentaine d'années. Formée dans les clubs parisiens, où elle tient une résidence au Pulp, elle sort le mix Feeling Strange chez Kompakt avant de fonder en 2011 le label Correspondant, prolongement de sa résidence au Rex Club. Elle dirige aussi Dischi Autunno et, depuis 2023, Færies Records, monté avec l'artiste et cinéaste Lou Fauroux.", en: "Jennifer Cardini is a French DJ and producer based in Berlin who has been behind the decks for some thirty years. She came up in Paris clubs, with a residency at Le Pulp, released the mix Feeling Strange on Kompakt, and in 2011 founded the label Correspondant as an extension of her Rex Club residency. She also runs Dischi Autunno and, since 2023, Færies Records, set up with the artist and filmmaker Lou Fauroux." }, origin: "France, installée à Berlin", labels: ["Correspondant", "Dischi Autunno", "Færies Records"], sources: ["https://djmag.com/news/jennifer-cardini-celebrates-30-years-djing-new-label-faeries-records", "https://correspondantmusic.com/jennifer-cardini/biography/"] }, // Jennifer Cardini
  "joachim-pastor": { slug: "joachim-pastor", bio: { fr: "Joachim Pastor est un DJ et producteur français originaire de Paris, rattaché à la scène techno mélodique. Il cofonde en 2013 le label et collectif Hungry Music avec Worakls et NTO, avant de rejoindre Armada Music en 2020 pour y publier son premier album, Greater Message. Sa musique, aux harmonies orchestrales et cinématographiques, s'est prolongée avec l'album PHANTOMGRID en 2025 et la bande originale du documentaire The Final Season.", en: "Joachim Pastor is a French DJ and producer from Paris, part of the melodic techno scene. He co-founded the Hungry Music label and collective with Worakls and NTO in 2013, then joined Armada Music in 2020 to release his first album, Greater Message. His music, built on orchestral and cinematic harmonies, continued with the album PHANTOMGRID in 2025 and the score for the documentary The Final Season." }, origin: "Paris, France", labels: ["Hungry Music", "Armada Music"], sources: ["https://www.armadamusic.com/artists/joachim-pastor-1", "https://en.wikipedia.org/wiki/Hungry_Music", "https://www.discogs.com/artist/1355294"] }, // Joachim Pastor
  "job-jobse": { slug: "job-jobse", bio: { fr: "Job Jobse est un DJ néerlandais installé à Amsterdam. Il a d'abord programmé le club Trouw, où il est passé d'assistant à responsable des bookings, avant de devenir résident de son successeur De School. En avril 2012, il fait venir Tale of Us pour la première soirée du label Life and Death, dont il devient ensuite le manager. Il a lancé en septembre 2025 son propre label, Planet Strangelove, inauguré par quatre relectures de « Pasion » de Pianoman.", en: "Job Jobse is a Dutch DJ based in Amsterdam. He first worked as a programmer at the Trouw club, rising from assistant to head booker, before becoming a resident at its successor De School. In April 2012 he booked Tale of Us for the first Life and Death label night, and went on to manage the label. In September 2025 he launched his own imprint, Planet Strangelove, opened by four reworks of Pianoman's \"Pasion\"." }, origin: "Amsterdam, Pays-Bas", labels: ["Planet Strangelove", "Life and Death"], sources: ["https://www.amsterdam-dance-event.nl/en/artists-speakers/job-jobse/20342/", "https://www.skiddle.com/news/all/Dutch-DJ-producer-Job-Jobse-launches-new-label-Planet-Strangelove/60530/"] }, // Job Jobse
  "joris-delacroix": { slug: "joris-delacroix", bio: { fr: "Joris Delacroix, né en 1987 à Montpellier, est un musicien, producteur et DJ français. Formé au piano dès quatre ans, il découvre la musique électronique à seize ans et publie son premier EP en 2008 sur Timid Records. Signé ensuite chez Way of House, il sort l'album Room With View en 2011, puis Going Back en 2016 et Night Visions en 2018 ; son répertoire relève de la house, de la deep house et de la techno mélodique.", en: "Joris Delacroix, born in 1987 in Montpellier, is a French musician, producer and DJ. Trained on piano from the age of four, he discovered electronic music at sixteen and released his first EP on Timid Records in 2008. Later signed to Way of House, he released the album Room With View in 2011, followed by Going Back in 2016 and Night Visions in 2018; his output sits in house, deep house and melodic techno." }, origin: "Montpellier, France", since: 2008, labels: ["Way of House", "Hungry Music"], sources: ["https://fr.wikipedia.org/wiki/Joris_Delacroix"] }, // Joris Delacroix
  "joris-voorn": { slug: "joris-voorn", bio: { fr: "Joris Voorn, né le 25 février 1977, est un DJ et producteur néerlandais qui vit à Amsterdam. Il a lancé sa carrière avec les EP « Muted Trax » (2002) et « Lost Memories » (2003), et a été élu talent de l'année aux Dutch DJ Awards en 2003. Il codirige avec Edwin Oosterwal les labels amstellodamois Green, fondé en 2005, et Rejected. Sa compilation Balance 014, parue en 2009, mélange cent morceaux sur un double CD.", en: "Joris Voorn, born 25 February 1977, is a Dutch DJ and producer who lives in Amsterdam. He launched his career with the EPs \"Muted Trax\" (2002) and \"Lost Memories\" (2003), and was named Talent of the Year at the Dutch DJ Awards in 2003. With Edwin Oosterwal he co-runs the Amsterdam labels Green, founded in 2005, and Rejected. His 2009 compilation Balance 014 blends one hundred tracks across a double CD." }, origin: "Amsterdam, Pays-Bas", since: 2002, labels: ["Green", "Rejected"], sources: ["https://en.wikipedia.org/wiki/Joris_Voorn"] }, // Joris Voorn
  "josh-baker": { slug: "josh-baker", bio: { fr: "Josh Baker est un DJ, producteur et patron de label britannique basé à Manchester, qui a commencé à mixer à 17 ans. Il produit une house minimale et deep tech, secteur dans lequel il a été l'artiste et le label les plus vendus sur Beatport. Il codirige le label et la soirée You&Me, a lancé le Hide&Seek Festival dans le nord-ouest de l'Angleterre, et cofondé la plateforme d'apprentissage en ligne Syntho Hub. Mixmag l'a cité parmi les DJ qui façonnent 2025.", en: "Josh Baker is a British DJ, producer and label owner based in Manchester, who started DJing at 17. He makes minimal and deep tech house, a field in which he has been Beatport's best-selling artist and label. He co-runs the You&Me label and party, launched the Hide&Seek Festival in North West England, and co-founded the online learning platform Syntho Hub. Mixmag named him among the DJs shaping 2025." }, origin: "Manchester, Royaume-Uni", labels: ["You&Me"], sources: ["https://www.internationalmusicsummit.com/ims-speakers/josh-baker"] }, // Josh Baker
  "jowi": { slug: "jowi", bio: { fr: "Jowi est une DJ et productrice suisse basée à Lugano, qui joue une hard techno industrielle teintée de gabber. En octobre 2025, elle cofonde avec Jazzy et Zatox le label KRAWALL Records, conçu comme un point de chute pour les artistes qui poussent la dance music vers le plus dur, quel que soit le genre. C'est là qu'est paru son single « Submerged » en juin 2026.", en: "Jowi is a Swiss DJ and producer based in Lugano who plays industrial hard techno with a gabber edge. In October 2025 she co-founded the label KRAWALL Records with Jazzy and Zatox, meant as a home for artists pushing dance music in a harder direction whatever the genre. Her single \"Submerged\" came out there in June 2026." }, origin: "Lugano, Suisse", since: 2025, labels: ["KRAWALL Records"], sources: ["https://www.musicnews.com/news/2026-06-14-jowi-releases-hard-techno-single-submerged-on-new-label-krawall-records"] }, // Jowi
  "joy-orbison": { slug: "joy-orbison", bio: { fr: "Joy Orbison, de son vrai nom Peter O'Grady, est un producteur et DJ anglais né en 1986 à Croydon, au sud de Londres. Sa musique croise house, dubstep, UK funky, UK garage et jungle, une combinaison qui a explosé avec « Hyph Mngo », paru chez Hotflush Recordings en 2009. Il a cofondé le label Hinge Finger en 2012 avec Will Bankhead et publié l'album Still Slipping Vol. 1 en 2021.", en: "Joy Orbison, real name Peter O'Grady, is an English producer and DJ born in 1986 in Croydon, south London. His music crosses house, dubstep, UK funky, UK garage and jungle, a mix that broke wide open with \"Hyph Mngo\", released on Hotflush Recordings in 2009. He co-founded the label Hinge Finger with Will Bankhead in 2012 and put out the album Still Slipping Vol. 1 in 2021." }, origin: "Croydon, Royaume-Uni", since: 2009, labels: ["Hinge Finger", "Hotflush Recordings"], sources: ["https://en.wikipedia.org/wiki/Joy_Orbison"] }, // Joy Orbison
  "kettama": { slug: "kettama", bio: { fr: "Evan Campbell, né en 1997 à Galway en Irlande, produit sous le nom de KETTAMA une house rapide teintée de rave. Il perce en 2018 avec « B O D Y », extrait de l'EP Bucklyn Bridge, relayé par Mall Grab et Annie Mac. En 2019, il cofonde avec Shampain le label G-Town Records, nommé d'après leur ville commune, et joue en 2024 à Glastonbury, Coachella et Boomtown.", en: "Born in Galway, Ireland in 1997, Evan Campbell produces fast, rave-tinged house as KETTAMA. He broke through in 2018 with \"B O D Y\" from the Bucklyn Bridge EP, picked up by Mall Grab and Annie Mac. In 2019 he co-founded the label G-Town Records with Shampain, named after their shared hometown, and in 2024 played Glastonbury, Coachella and Boomtown." }, origin: "Galway, Irlande", since: 2018, labels: ["G-Town Records"], sources: ["https://en.wikipedia.org/wiki/Kettama"] }, // Kettama
  "kevin-de-vries": { slug: "kevin-de-vries", bio: { fr: "Originaire d'une zone rurale près de Cologne, Kevin de Vries s'est installé à Berlin après des années d'allers-retours le week-end, et n'a quitté son emploi de responsable de supermarché qu'en novembre 2019. Il produit une techno mélodique traversée de trance, entièrement dans l'ordinateur, et a sorti sur Afterlife, Cocoon et Anjunadeep, notamment les titres « Arakat » et « Meraki » et un remix de « Saltwater » de Chicane. Il a longtemps tenu une résidence au club Tama, à Poznań.", en: "Raised in the countryside outside Cologne, Kevin de Vries moved to Berlin after years of weekend trips, and only left his supermarket management job in November 2019. He produces trance-inflected melodic techno entirely in the box, releasing on Afterlife, Cocoon and Anjunadeep, including the tracks \"Arakat\" and \"Meraki\" and a remix of Chicane's \"Saltwater\". He has held a long-running residency at the Tama club in Poznań." }, origin: "Région de Cologne, Allemagne", labels: ["Afterlife", "Cocoon", "Anjunadeep"], sources: ["https://www.beatportal.com/articles/324403-introducing-kevin-de-vries-afterlifes-unstoppable-new-talent"] }, // Kevin de Vries
  "ki-ki": { slug: "ki-ki", bio: { fr: "KI/KI, de son vrai nom Kiki Wesselo, née le 30 août 1996 à Epe, est une DJ et productrice néerlandaise. Ses sets mêlent trance, acid techno et sonorités rave des années 1990 ; elle s'est fait connaître comme résidente de la soirée queer Spielraum à Amsterdam. Elle a fondé le label slash en 2022 et a remporté en 2025 la catégorie Dance des Edison Awards, première femme à y parvenir.", en: "KI/KI, real name Kiki Wesselo, born 30 August 1996 in Epe, is a Dutch DJ and producer. Her sets blend trance, acid techno and 1990s rave sounds; she first became known as a resident of the queer party Spielraum in Amsterdam. She founded the label slash in 2022 and in 2025 won the Dance category at the Edison Awards, the first woman to do so." }, origin: "Epe / Amsterdam, Pays-Bas", since: 2018, labels: ["slash"], sources: ["https://en.wikipedia.org/wiki/KI/KI"], photo: { file: "ki-ki.webp", author: "Charlestpt", license: "CC BY-SA 4.0", page: "https://commons.wikimedia.org/wiki/File:KI_KI_Phantom_2026.02.14_-_003.jpg" } }, // KI/KI
  "klangkuenstler": { slug: "klangkuenstler", bio: { fr: "Michael Korb, né en 1990 à Füssen en Bavière, s'installe à Berlin à l'été 2012 après un premier set au Ritter Butzke. Il fonde le label Zuckerton Records en 2011 puis Outworld en 2019, joue d'abord de la deep et de la tech house avant de basculer vers la techno à partir de 2018. En octobre 2023, il cofonde avec le DJ Kobosil la structure Tote Sonne, à la fois label et agence d'artistes.", en: "Born in Füssen, Bavaria in 1990, Michael Korb moved to Berlin in the summer of 2012 after an early set at the club Ritter Butzke. He founded the label Zuckerton Records in 2011 and Outworld in 2019, playing deep and tech house before shifting towards techno from 2018 onwards. In October 2023 he co-founded Tote Sonne, a label and artist agency, with fellow DJ Kobosil." }, origin: "Füssen, Bavière, Allemagne", since: 2011, labels: ["Zuckerton Records", "Outworld", "Tote Sonne"], sources: ["https://en.wikipedia.org/wiki/Klangkuenstler", "https://de.wikipedia.org/wiki/Klangkuenstler"], photo: { file: "klangkuenstler.webp", author: "Medusa Festival", license: "CC BY 3.0", page: "https://commons.wikimedia.org/wiki/File:Klangkuenstler_in_2024_Medusa_Festival_podcast.png" } }, // Klangkuenstler
  "kobosil": { slug: "kobosil", bio: { fr: "Max Kobosil, né en 1991 à Berlin-Neukölln, produit une techno rapide et abrasive nourrie d'EBM, de noise et d'industriel. Résident du Berghain de décembre 2014 à 2019, il fonde en 2013 son label RK, devenu R Label Group, et sort l'album « We Grow, You Decline » en 2016. En octobre 2023, il cofonde avec le DJ Klangkuenstler la structure Tote Sonne, à la fois label et agence d'artistes.", en: "Born in 1991 in Berlin's Neukölln district, Max Kobosil makes fast, abrasive techno drawing on EBM, noise and industrial. A resident at Berghain from December 2014 through 2019, he founded his RK label in 2013 — later R Label Group — and released the album \"We Grow, You Decline\" in 2016. In October 2023 he co-founded Tote Sonne, a label and artist agency, with fellow DJ Klangkuenstler." }, origin: "Berlin, Allemagne", since: 2013, labels: ["R Label Group", "Tote Sonne"], sources: ["https://en.wikipedia.org/wiki/Kobosil"], photo: { file: "kobosil.webp", author: "Rayukk", license: "CC BY-SA 4.0", page: "https://commons.wikimedia.org/wiki/File:Kobosil_Kamehameha_Festival_15_Juni_2019.jpg" } }, // Kobosil
  "kolsch": { slug: "kolsch", bio: { fr: "Rune Reilly Kölsch, né en 1977 dans le quartier libre de Christiania à Copenhague, est un producteur et DJ danois. Sa house mélodique et sa techno paraissent principalement chez Kompakt, le label de Cologne, depuis son premier album en 2013. Avant d'adopter ce nom, il avait signé « Calabria » (2003) sous l'alias Rune, un morceau au riff de saxophone synthétique devenu un standard des clubs.", en: "Rune Reilly Kölsch, born in 1977 in Copenhagen's free town of Christiania, is a Danish producer and DJ. His melodic house and techno appear mainly on the Cologne label Kompakt, where he has released albums since 2013. Before adopting that name he cut \"Calabria\" (2003) as Rune, a track built on a synthetic saxophone riff that became a club standard." }, origin: "Copenhague, Danemark", since: 1995, labels: ["Kompakt"], sources: ["https://en.wikipedia.org/wiki/K%C3%B6lsch_(musician)", "https://en.wikipedia.org/wiki/Calabria_(song)"], photo: { file: "kolsch.webp", author: "Robin Krahl", license: "CC BY-SA 4.0", page: "https://commons.wikimedia.org/wiki/File:2015-07-19_6748_K%C3%B6lsch_(Sea_You).jpg" } }, // Kölsch
  "konstantin-sibold": { slug: "konstantin-sibold", bio: { fr: "DJ et producteur allemand établi à Stuttgart, Konstantin Sibold s'est fait connaître en 2013 avec « Madeleine », paru sur le label Innervisions. Il a ensuite sorti « Mutter » sur Running Back et « Shake This World » sur Afterlife, et publié également chez Drumcode et Anjunadeep. Ses sets mélangent house, techno, acid et EBM, entre le Berghain, le Fabric de Londres et le Pacha d'Ibiza.", en: "A German DJ and producer based in Stuttgart, Konstantin Sibold made his name in 2013 with \"Madeleine\", released on the Innervisions label. He went on to put out \"Mutter\" on Running Back and \"Shake This World\" on Afterlife, and has also released through Drumcode and Anjunadeep. His sets move between house, techno, acid and EBM, from Berghain to Fabric in London and Pacha in Ibiza." }, origin: "Stuttgart, Allemagne", since: 2013, labels: ["Innervisions", "Running Back", "Afterlife"], sources: ["https://www.auroratalent.agency/konstantinsibold.html"] }, // Konstantin Sibold
  "lil-texas": { slug: "lil-texas", bio: { fr: "Lil Texas est un producteur et DJ américain né à Dallas et installé à Los Angeles, formé au Berklee College of Music. Il pousse le hardcore au-delà de 200 BPM et a baptisé son style « texcore » : influence gabber old school, mélodies et breakdowns hérités du hardcore des débuts, stabs de synthé et samples d'horreur. Son esthétique de cow-boy à strass va de pair avec ses EP Texcore.", en: "Lil Texas is an American producer and DJ, born in Dallas and based in Los Angeles, who trained at Berklee College of Music. He pushes hardcore past 200 BPM and coined the name \"texcore\" for his style: old-school gabber influence, melodies and breakdowns inherited from early hardcore, synth stabs and horror samples. The rhinestone-cowboy look is part of the package, as are his Texcore EPs." }, origin: "Dallas, États-Unis", sources: ["https://www.thefader.com/2019/11/26/lil-texas-interview"] }, // Lil Texas
  "luca-agnelli": { slug: "luca-agnelli", bio: { fr: "Luca Agnelli est un DJ et producteur italien originaire de Toscane. Sa techno dure et physique garde des racines house, et se teinte volontiers d'industriel et de neo rave. Il a fondé en 2010 le label Etruria Beat, devenu l'une des références italiennes du genre, et signé en 2016 un remix de « Porcelain » de Moby paru sur Drumcode. Il joue régulièrement à l'Amnesia d'Ibiza, à la Fabrique de Milan, à l'Egg de Londres ou au Movement Festival de Turin.", en: "Luca Agnelli is an Italian DJ and producer from Tuscany. His hard, physical techno keeps its house roots while leaning into industrial and neo-rave textures. He founded the label Etruria Beat in 2010, now one of Italy's reference imprints for the style, and in 2016 delivered a remix of Moby's \"Porcelain\" released on Drumcode. He plays regularly at Amnesia in Ibiza, Fabrique in Milan, Egg in London and Turin's Movement Festival." }, origin: "Toscane, Italie", since: 2010, labels: ["Etruria Beat"], sources: ["https://electronicgroove.com/eg-artists/eg-techno-020-luca-agnelli/"] }, // Luca Agnelli
  "maceo-plex": { slug: "maceo-plex", bio: { fr: "Eric Estornel, né en 1978 aux États-Unis et élevé entre Dallas et Miami, produit sous les alias Maceo Plex, Maetrik et Mariel Ito une musique qui mêle house, techno et electro. Son premier album, « Life Index », paraît sur Crosstown Rebels en 2011 ; il dirige ensuite ses propres labels Ellum Audio puis Lone Romantic, sur lesquels sortent « Journey to Solar » (2016), « Solar » (2017) et « Mutant Series » (2019). Depuis 2016, il tient à Ibiza sa soirée Mosaic by Maceo au Pacha. Il vit aujourd'hui à Barcelone.", en: "Born in 1978 in the United States and raised between Dallas and Miami, Eric Estornel produces as Maceo Plex, Maetrik and Mariel Ito, mixing house, techno and electro. His first album \"Life Index\" came out on Crosstown Rebels in 2011; he went on to run his own labels Ellum Audio and Lone Romantic, home to \"Journey to Solar\" (2016), \"Solar\" (2017) and \"Mutant Series\" (2019). Since 2016 he has hosted his Mosaic by Maceo night at Pacha in Ibiza. He now lives in Barcelona." }, origin: "Dallas / Miami, États-Unis", labels: ["Ellum Audio", "Lone Romantic"], sources: ["https://en.wikipedia.org/wiki/Maceo_Plex"], photo: { file: "maceo-plex.webp", author: "Robin Krahl", license: "CC BY-SA 4.0", page: "https://commons.wikimedia.org/wiki/File:2015-07-19_6886_Maceo_Plex_(Sea_You).jpg" } }, // Maceo Plex
  "mad-dog": { slug: "mad-dog", bio: { fr: "Mad Dog, de son vrai nom Filippo Calcagni, né le 2 novembre 1980 à Rome, est un DJ et producteur italien de hardcore et de gabber, installé aux Pays-Bas. À 16 ans il forme le groupe Hardcore Terrorists, puis part en solo à l'été 2000 et signe chez Traxtorm Records, le label du duo The Stunned Guys. Il a publié les albums A Night of Madness (2011), Rudeness: Hardcore Beyond the Rules (2013) et Till I Die (2017), et a fondé en 2016 son propre label, Dogfight Records.", en: "Mad Dog, real name Filippo Calcagni, born 2 November 1980 in Rome, is an Italian hardcore and gabber DJ and producer now living in the Netherlands. At 16 he formed the group Hardcore Terrorists, went solo in the summer of 2000 and signed to Traxtorm Records, the label run by the duo The Stunned Guys. He released the albums A Night of Madness (2011), Rudeness: Hardcore Beyond the Rules (2013) and Till I Die (2017), and founded his own label, Dogfight Records, in 2016." }, origin: "Rome, Italie", since: 2000, labels: ["Dogfight Records", "Traxtorm Records"], sources: ["https://en.wikipedia.org/wiki/DJ_Mad_Dog", "https://it.wikipedia.org/wiki/DJ_Mad_Dog"] }, // Mad Dog
  "mala": { slug: "mala", bio: { fr: "Mala, de son vrai nom Mark Lawrence, est un producteur et DJ britannique originaire de South Norwood, dans le sud de Londres. Il est l'une des deux moitiés du duo dubstep Digital Mystikz avec Coki, et cofondateur du label et de la soirée DMZ à Brixton aux côtés de Coki, Loefah et Sgt. Pokes. Il dirige aussi son propre label, Deep Medi Musik. Son album « Mala in Cuba », enregistré à La Havane avec Gilles Peterson, est paru en 2012.", en: "Mala, real name Mark Lawrence, is a British producer and DJ from South Norwood in south London. He is one half of the dubstep duo Digital Mystikz alongside Coki, and co-founder of the DMZ label and club night in Brixton with Coki, Loefah and Sgt. Pokes. He also runs his own imprint, Deep Medi Musik. His album \"Mala in Cuba\", recorded in Havana with Gilles Peterson, came out in 2012." }, origin: "Londres, Royaume-Uni", since: 2004, labels: ["Deep Medi Musik", "DMZ"], sources: ["https://en.wikipedia.org/wiki/Mala_(musician)"] }, // Mala
  "maribou-state": { slug: "maribou-state", bio: { fr: "Maribou State est un duo électronique anglais formé par Chris Davids et Liam Ivory, originaires de Berkhamsted dans le Hertfordshire, où ils se sont rencontrés au lycée. Ils débutent en 2011 avec l'EP Habitat sur FatCat Records, puis signent chez Counter Records, filiale de Ninja Tune. Leurs albums Portraits (2015), Kingdoms in Colour (2018) et Hallucinating Love (2025) mêlent house, soul et voix invitées, dont celles de Holly Walker et Khruangbin.", en: "Maribou State is an English electronic duo made up of Chris Davids and Liam Ivory, from Berkhamsted in Hertfordshire, where they met at school. They debuted in 2011 with the EP Habitat on FatCat Records, then signed to Counter Records, an imprint of Ninja Tune. Their albums Portraits (2015), Kingdoms in Colour (2018) and Hallucinating Love (2025) blend house, soul and guest vocals, including Holly Walker and Khruangbin." }, origin: "Berkhamsted, Angleterre", since: 2011, labels: ["Counter Records", "Ninja Tune"], sources: ["https://en.wikipedia.org/wiki/Maribou_State"] }, // Maribou State
  "marie-vaunt": { slug: "marie-vaunt", bio: { fr: "Bobbie Merveille, née en 1983 à Seattle et élevée au Japon jusqu'à ses quatorze ans, a d'abord mixé sous le nom DJ Heavygrinder avant d'adopter l'alias Marie Vaunt en 2018. Installée à Los Angeles, elle produit une techno acide et rapide où affleurent ses racines japonaises, comme sur « Kurayami ». Elle a sorti chez Drumcode et sur HILOMATIK, le label de HI-LO.", en: "Bobbie Merveille, born in Seattle in 1983 and raised in Japan until she was fourteen, first DJed as DJ Heavygrinder before taking the Marie Vaunt alias in 2018. Based in Los Angeles, she produces fast, acid-leaning techno in which her Japanese roots surface, as on \"Kurayami\". She has released on Drumcode and on HILOMATIK, HI-LO's label." }, origin: "Seattle, États-Unis", since: 2018, labels: ["Drumcode", "HILOMATIK"], sources: ["https://en.wikipedia.org/wiki/DJ_Heavygrinder", "https://www.beatportal.com/articles/942047-marie-vaunt-bridging-cultures-through-techno"], photo: { file: "marie-vaunt.webp", author: "Florida Supercon (Flickr)", license: "CC BY-SA 2.0", page: "https://commons.wikimedia.org/wiki/File:DJ_Heavygrinder_at_FSC_2008.jpeg" } }, // Marie Vaunt
  "marlon-hoffstadt": { slug: "marlon-hoffstadt", bio: { fr: "Marlon Hoffstadt est un DJ et producteur allemand né et installé à Berlin, également connu sous l'alias DJ Daddy Trance. Il se fait remarquer en 2014 avec le single « Shake That », produit avec Dansson, puis lance son label Midnight Themes en 2017 et la série de soirées Savour The Moment au club Wilde Renate. Ses sets circulent entre disco, house, trance et techno.", en: "Marlon Hoffstadt is a German DJ and producer born and based in Berlin, also known under the alias DJ Daddy Trance. He first drew attention in 2014 with the single \"Shake That\", made with Dansson, then launched his label Midnight Themes in 2017 and the Savour The Moment party series at the Wilde Renate club. His sets move between disco, house, trance and techno." }, origin: "Berlin, Allemagne", since: 2012, labels: ["Midnight Themes", "Retrograde"], sources: ["https://djmag.com/content/cue-marlon-hoffstadt", "https://www.discogs.com/artist/2623061"] }, // Marlon Hoffstadt
  "marshmello": { slug: "marshmello", bio: { fr: "Marshmello est le nom de scène de Christopher Comstock, producteur et DJ américain né en 1992 à Philadelphie, qui se produit masqué sous un casque blanc en forme de guimauve. Il a adopté ce pseudonyme en 2015 après avoir publié sous le nom de Dotcom, et son identité a été confirmée par Forbes en 2017. Sa musique, très portée sur les synthés et les basses, croise dubstep, future bass et trap : « Silence » avec Khalid, « Wolves » avec Selena Gomez ou « Happier » avec Bastille. Il a fondé son label indépendant Joytime Collective en 2016.", en: "Marshmello is the stage name of Christopher Comstock, an American producer and DJ born in Philadelphia in 1992, who performs masked under a white marshmallow-shaped helmet. He took the alias in 2015 after releasing as Dotcom, and his identity was confirmed by Forbes in 2017. His synth- and bass-heavy music crosses dubstep, future bass and trap: \"Silence\" with Khalid, \"Wolves\" with Selena Gomez, \"Happier\" with Bastille. He founded his independent label Joytime Collective in 2016." }, origin: "Philadelphie, États-Unis", since: 2015, labels: ["Joytime Collective"], sources: ["https://en.wikipedia.org/wiki/Marshmello"], photo: { file: "marshmello.webp", author: "Stefan Brending (2eight)", license: "CC BY-SA 3.0", page: "https://commons.wikimedia.org/wiki/File:2016_Open_Beatz_-_Marshmello_-_by_2eight_-DSC_4448.jpg" } }, // Marshmello
  "martin-garrix": { slug: "martin-garrix", bio: { fr: "Martin Garrix, de son vrai nom Martijn Gerard Garritsen, est un DJ et producteur néerlandais né en 1996 à Amstelveen. Il produit de la progressive house et de la big room house. Son morceau « Animals », sorti en 2013, l'a propulsé à 17 ans en tête du classement Beatport. Il a fondé son label Stmpd Rcrds en 2016 et a été classé numéro un du Top 100 DJs de DJ Mag en 2016, 2017, 2018, 2022 et 2024.", en: "Martin Garrix, real name Martijn Gerard Garritsen, is a Dutch DJ and producer born in 1996 in Amstelveen. He makes progressive house and big room house. His track \"Animals\", released in 2013, took him to the top of the Beatport chart at 17. He founded his label Stmpd Rcrds in 2016 and topped DJ Mag's Top 100 DJs poll in 2016, 2017, 2018, 2022 and 2024." }, origin: "Amstelveen, Pays-Bas", since: 2013, labels: ["Stmpd Rcrds"], sources: ["https://en.wikipedia.org/wiki/Martin_Garrix"], photo: { file: "martin-garrix.webp", author: "Moiyeah", license: "CC BY-SA 4.0", page: "https://commons.wikimedia.org/wiki/File:Martin_Garrix_-_Superbloom_Festival_2023_-_DSC2689_(cropped).jpg" } }, // Martin Garrix
  "mathew-jonson": { slug: "mathew-jonson", bio: { fr: "Mathew Jonson est un producteur et DJ canadien originaire de Vancouver, aujourd'hui installé à Berlin. Formé au piano classique et à la batterie jazz, il a mis la main sur un synthétiseur à neuf ans et sorti son premier single, « New Identity », sur le label britanno-colombien Itiswhatitis en 2001. Il a cofondé le label Wagon Repair en 2005 et joue aussi au sein des formations Cobblestone Jazz et Midnight Operator. Ses live sets sont entièrement joués en temps réel sur des machines analogiques, sans lecture de fichiers préparés.", en: "Mathew Jonson is a Canadian producer and DJ from Vancouver, now based in Berlin. Trained on classical piano and jazz drums, he got his hands on a synthesiser at nine and released his first single, \"New Identity\", on the British Columbia label Itiswhatitis in 2001. He co-founded the Wagon Repair label in 2005 and also plays in the groups Cobblestone Jazz and Midnight Operator. His live sets are performed in real time on analogue gear rather than played back from prepared files." }, origin: "Vancouver, Canada", since: 2001, labels: ["Wagon Repair", "Itiswhatitis"], sources: ["https://grayarea.co/artists/mathew-jonson"] }, // Mathew Jonson
  "matrakk": { slug: "matrakk", bio: { fr: "Matrakk est un DJ et producteur français qui mêle techno, trance et groove, avec des synthés et des voix qui rejouent l'esprit des raves des années 1990. Il a commencé comme DJ généraliste avant de se former à l'école de DJ de l'UCPA, et a cofondé le label Obsession avec R Organic. Sa percée date de « My Drums Hard » (2020) ; il a publié l'album Contre-Sens II en janvier 2024, puis « Romance Under The Sun » sur Speed Master la même année.", en: "Matrakk is a French DJ and producer whose sound mixes techno, trance and groove, with synths and vocals that replay the spirit of 1990s raves. He started out as an all-round DJ before training at the UCPA DJ school, and co-founded the Obsession label with R Organic. His breakthrough came with \"My Drums Hard\" (2020); he released the album Contre-Sens II in January 2024, followed by \"Romance Under The Sun\" on Speed Master the same year." }, origin: "France", since: 2020, labels: ["Obsession"], sources: ["https://electro-news.eu/matrakk-le-dj-generaliste-lyonnais-devenu-ambassadeur-de-la-rave-90s-dans-le-monde-entier/", "https://nuits-sonores.com/en/artiste/matrakk-2/"] }, // Matrakk
  "mau-p": { slug: "mau-p", bio: { fr: "Maurits Westveen, né à Amsterdam en 1996, a d'abord produit sous le nom de Maurice West avant d'adopter l'alias Mau P en 2022. Son morceau « Drugs from Amsterdam », sorti la même année, s'est hissé en tête du classement général de Beatport et a été retenu par Billboard parmi les meilleurs titres dance de 2022. Sa tech house sombre est parue sur des labels comme Repopulate Mars, Diynamic, Defected et Afterlife.", en: "Born in Amsterdam in 1996, Maurits Westveen produced as Maurice West before adopting the Mau P alias in 2022. His track \"Drugs from Amsterdam\", released that same year, topped Beatport's main chart and was named by Billboard among the best dance tracks of 2022. His dark tech house has appeared on labels including Repopulate Mars, Diynamic, Defected and Afterlife." }, origin: "Amsterdam, Pays-Bas", since: 2022, labels: ["Repopulate Mars", "Diynamic", "Defected"], sources: ["https://en.wikipedia.org/wiki/Mau_P"], photo: { file: "mau-p.webp", author: "Medusa Festival", license: "CC BY 3.0", page: "https://commons.wikimedia.org/wiki/File:Mau_P_in_Medusa_Festival_podcast.png" } }, // Mau P
  "mind-against": { slug: "mind-against", bio: { fr: "Mind Against est un duo italien formé par les frères Alessandro et Federico Fognini, installé à Berlin. Leur musique croise IDM, house et techno, avec des mélodies héritées des bandes originales des années 1980 et un fort travail de sound design. Ils se font connaître en 2013 avec l'EP « Atlant » sur Life and Death, puis publient sur Afterlife — le label de Tale of Us — où sort en 2020 leur titre « Walking Away », ainsi que sur Hotflush et Cocoon.", en: "Mind Against is an Italian duo made up of brothers Alessandro and Federico Fognini, based in Berlin. Their music sits between IDM, house and techno, with melodies borrowed from 1980s soundtracks and a heavy emphasis on sound design. They broke through in 2013 with the EP \"Atlant\" on Life and Death, then released on Afterlife — Tale of Us's label, home to their 2020 track \"Walking Away\" — as well as Hotflush and Cocoon." }, origin: "Italie, installés à Berlin", since: 2013, labels: ["Afterlife", "Life and Death"], sources: ["https://www.awakenings.com/en/artists/mind-against/1010/"] }, // Mind Against
  "miss-k8": { slug: "miss-k8", bio: { fr: "Kateryna Kremko, connue sous le nom de Miss K8, est une DJ et productrice ukrainienne née à Kiev. Elle joue du hardcore et du gabber, et signe dès 2012 sur le label néerlandais Masters of Hardcore, où paraît son premier single « Unforgettable ». Elle est depuis une habituée des grandes scènes hard dance européennes, de Masters of Hardcore à Defqon.1.", en: "Kateryna Kremko, better known as Miss K8, is a Ukrainian DJ and producer born in Kyiv. She plays hardcore and gabber, and signed in 2012 to the Dutch label Masters of Hardcore, which put out her first single \"Unforgettable\". She has been a regular on Europe's main hard dance stages ever since, from Masters of Hardcore to Defqon.1." }, origin: "Kiev, Ukraine", since: 2012, labels: ["Masters of Hardcore"], sources: ["https://en.wikipedia.org/wiki/Miss_K8"], photo: { file: "miss-k8.webp", author: "Caesar", license: "CC BY-SA 4.0", page: "https://commons.wikimedia.org/wiki/File:Miss_K8_at_Summerburst_2016.jpg" } }, // Miss K8
  "miss-monique": { slug: "miss-monique", bio: { fr: "Miss Monique, de son vrai nom Alesia Arkusha, est une DJ et productrice ukrainienne née en 1992 à Kirovohrad (aujourd'hui Kropyvnytskyï) et formée à Kiev. Elle joue de la progressive house et de la techno mélodique, et s'est fait connaître par ses émissions vidéo « Mind Games » et « MiMo Weekly ». Elle a fondé son label Siona Records en 2019 et sorti des titres sur Armada, Drumcode, Black Hole Recordings et Tomorrowland Music. Elle a été élue révélation de l'année aux DJ Awards en 2024.", en: "Miss Monique, real name Alesia Arkusha, is a Ukrainian DJ and producer born in 1992 in Kirovohrad (now Kropyvnytskyi) and raised as a DJ in Kyiv. She plays progressive house and melodic techno, and built her audience through the video shows \"Mind Games\" and \"MiMo Weekly\". She founded her label Siona Records in 2019 and has released on Armada, Drumcode, Black Hole Recordings and Tomorrowland Music. She won Breakthrough Artist at the DJ Awards in 2024." }, origin: "Kropyvnytskyï, Ukraine", since: 2013, labels: ["Siona Records"], sources: ["https://en.wikipedia.org/wiki/Miss_Monique"], photo: { file: "miss-monique.webp", author: "Kate Martin", license: "CC0", page: "https://commons.wikimedia.org/wiki/File:Miss_Monique_(Feb_%2726).tif" } }, // Miss Monique
  "modeselektor": { slug: "modeselektor", bio: { fr: "Modeselektor est un duo électronique allemand formé par Gernot Bronsert et Sebastian Szary, qui se sont rencontrés à Berlin en 1992 dans les fêtes clandestines de l'après-Mur. Leur nom vient d'une fonction de l'écho à bande Roland Space Echo. Signés chez BPitch Control à partir de 2000, ils publient Hello Mom! (2005) et Happy Birthday! (2007), où chante Thom Yorke, puis fondent leur label Monkeytown Records. Avec Apparat, ils forment le groupe Moderat.", en: "Modeselektor is a German electronic duo made up of Gernot Bronsert and Sebastian Szary, who met in Berlin in 1992 at the illegal parties that followed the fall of the Wall. Their name comes from a function on the Roland Space Echo tape unit. Signed to BPitch Control from 2000, they released Hello Mom! (2005) and Happy Birthday! (2007), which features Thom Yorke, then founded their label Monkeytown Records. With Apparat they form the group Moderat." }, origin: "Berlin, Allemagne", since: 2000, labels: ["Monkeytown Records", "BPitch Control"], sources: ["https://en.wikipedia.org/wiki/Modeselektor"], photo: { file: "modeselektor.webp", author: "Matt Biddulph", license: "CC BY-SA 2.0", page: "https://commons.wikimedia.org/wiki/File:Modeselektor,_2009.jpg" } }, // Modeselektor
  "moodymann": { slug: "moodymann", bio: { fr: "Moodymann est le nom de scène de Kenny Dixon Jr., musicien américain établi à Détroit. Sa house et sa techno sont bâties sur des boucles de disques soul, funk et disco chinés puis rejouées. Il lance son label KDJ Records en 1994 avec l'EP Moody Trax, publie son premier album Silentintroduction en 1997 sur Planet E Communications, et dirige aussi Mahogani Music. Il fait partie du trio 3 Chairs.", en: "Moodymann is the stage name of Kenny Dixon Jr., an American musician based in Detroit. His house and techno are built on loops lifted from soul, funk and disco records and reworked. He started his label KDJ Records in 1994 with the EP Moody Trax, released his debut album Silentintroduction in 1997 on Planet E Communications, and also runs Mahogani Music. He is a member of the trio 3 Chairs." }, origin: "Détroit, États-Unis", since: 1994, labels: ["KDJ Records", "Mahogani Music"], sources: ["https://en.wikipedia.org/wiki/Moodymann"], photo: { file: "moodymann.webp", author: "acidpolly", license: "CC BY-SA 2.0", page: "https://commons.wikimedia.org/wiki/File:Sonar_2010_-_Moodymann.jpg" } }, // Moodymann
  "netsky": { slug: "netsky", bio: { fr: "Netsky est le nom de scène de Boris Daenen, né le 22 mars 1989, producteur belge de drum and bass originaire d'Anvers — son alias reprend le nom d'un virus informatique. Il signe fin 2009 chez Hospital Records, label du liquid funk, et sort son premier album Netsky en 2010, suivi de 2 (2012), 3 (2016) et Second Nature (2020). En 2015, il est le premier DJ producteur à recevoir le prix flamand de la Culture pour la musique.", en: "Netsky is the stage name of Boris Daenen, born 22 March 1989, a Belgian drum and bass producer from Antwerp — his alias is taken from a computer virus. He signed to liquid funk label Hospital Records in late 2009 and released his debut album Netsky in 2010, followed by 2 (2012), 3 (2016) and Second Nature (2020). In 2015 he became the first DJ and producer to receive the Flemish Culture Prize for music." }, origin: "Anvers, Belgique", since: 2009, labels: ["Hospital Records"], sources: ["https://en.wikipedia.org/wiki/Netsky_(musician)"], photo: { file: "netsky.webp", author: "James Starkey", license: "CC BY 2.0", page: "https://commons.wikimedia.org/wiki/File:Netsky_(DJ)_2008.jpg" } }, // Netsky
  "nico-moreno": { slug: "nico-moreno", bio: { fr: "Nico Moreno, de son vrai nom Nicolas Bloche, est un DJ et producteur français né le 20 août 1994 à Caen. Il produit une techno industrielle rapide nourrie de gabber, de hardcore et d'acid, et publie ses premiers titres à partir de 2017. En 2019, il quitte le label BlvckPlvgue pour fonder Insolent Rave Records, où sort son morceau de rupture « Purple Widow ». Il a joué la mainstage de Tomorrowland en 2025 et figure au 67e rang du Top 100 DJs de DJ Mag la même année.", en: "Nico Moreno, born Nicolas Bloche on 20 August 1994 in Caen, is a French DJ and producer. He makes fast industrial techno fed by gabber, hardcore and acid, and released his first tracks from 2017 onwards. In 2019 he left the BlvckPlvgue label to found Insolent Rave Records, home to his breakout track \"Purple Widow\". He played the Tomorrowland main stage in 2025 and entered DJ Mag's Top 100 DJs at number 67 the same year." }, origin: "Caen, France", since: 2017, labels: ["Insolent Rave Records"], sources: ["https://fr.wikipedia.org/wiki/Nico_Moreno", "https://djmag.com/top100djs/2025/67/nico-moreno"], photo: { file: "nico-moreno.webp", author: "Vesuve1 (photo : Samuel Nogues)", license: "CC BY-SA 4.0", page: "https://commons.wikimedia.org/wiki/File:Nico_Moreno._Photo_de_Nico_Moreno_par_Samuel_Nogues.jpg" } }, // Nico Moreno
  "nikolina": { slug: "nikolina", bio: { fr: "Nikolina, de son prénom Ronja, est une DJ allemande basée à Berlin. Elle fréquente les raves berlinoises dès quatorze ans et tourne professionnellement depuis 2021. Elle appelle « Schroove » son mélange de schranz et de groove, une hard techno pensée pour le corps avant la tête. On la retrouve sur les affiches du circuit hard techno européen, du Bootshaus de Cologne au festival Verknipt.", en: "Nikolina, first name Ronja, is a German DJ based in Berlin. She started going to Berlin raves at fourteen and has been touring professionally since 2021. She calls her blend of schranz and groove \"Schroove\" — hard techno built to hit the body before the mind. She is a regular on the European hard techno circuit, from Cologne's Bootshaus to the Verknipt festival." }, origin: "Berlin, Allemagne", since: 2021, sources: ["https://www.nastymagazine.com/music/schroove-rising-nikolina/", "https://bootshaus.tv/events/unreal-weekender-night-i-september-2026/"] }, // Nikolina
  "nina-kraviz": { slug: "nina-kraviz", bio: { fr: "Née et élevée à Irkoutsk, en Sibérie, Nina Kraviz part étudier la dentisterie à Moscou, anime une émission de radio et tient une résidence au club Propaganda avant de vivre de la musique. Son premier album éponyme paraît en 2012 sur Rekids, elle fonde son label трип (Trip) en 2014 et mixe le quarante-huitième volume de la série DJ-Kicks en 2015. Elle a également composé pour le jeu Cyberpunk 2077, où elle apparaît en caméo.", en: "Born and raised in Irkutsk, Siberia, Nina Kraviz studied dentistry in Moscow, hosted a radio show and held a residency at the Propaganda club before making a living from music. Her self-titled debut album came out on Rekids in 2012, she founded her трип (Trip) label in 2014 and mixed the forty-eighth DJ-Kicks volume in 2015. She also wrote music for the game Cyberpunk 2077, in which she makes a cameo appearance." }, origin: "Irkoutsk, Russie", since: 2012, labels: ["трип (Trip)", "Rekids"], sources: ["https://en.wikipedia.org/wiki/Nina_Kraviz"], photo: { file: "nina-kraviz.webp", author: "Alec Luhn", license: "CC BY 2.0", page: "https://commons.wikimedia.org/wiki/File:Nina_Kraviz,_2012.jpg" } }, // Nina Kraviz
  "novah": { slug: "novah", bio: { fr: "Novah, de son vrai nom Noa Heyse, est une DJ et productrice belge originaire d'Anvers. Ses productions relèvent du hard techno et intègrent des éléments d'acid, de techno industrielle et de psytrance. Elle publie son premier titre, « A Savage », en 2023 sur le label Taapion de Shlømo, puis sort sur Revised Records, Teletech, Tomorrowland Music et la compilation anniversaire d'Exhale Records.", en: "Novah, real name Noa Heyse, is a Belgian DJ and producer from Antwerp. Her productions sit in hard techno and take in acid, industrial techno and psytrance. She released her first track, \"A Savage\", in 2023 on Shlømo's Taapion label, then appeared on Revised Records, Teletech, Tomorrowland Music and the anniversary compilation of Amelie Lens's Exhale Records." }, origin: "Anvers, Belgique", since: 2022, labels: ["Taapion", "Revised Records", "Tomorrowland Music"], sources: ["https://fr.wikipedia.org/wiki/Novah"] }, // Novah
  "nto": { slug: "nto", bio: { fr: "NTO, de son vrai nom Anthony Favier, né en 1985 à Marseille, est un producteur et compositeur français de techno mélodique. Il publie son premier EP, Traque, en 2008 sur Basilic Records sous le nom N'to, puis cofonde en 2013 le collectif et label Hungry Music avec Worakls et Joachim Pastor. Il quitte Hungry Music en 2020 et sort l'album Apnea en 2021 sur AllPoints, suivi de Forever Friends avec le pianiste Sofiane Pamart en 2024.", en: "NTO, real name Anthony Favier, born in 1985 in Marseille, is a French melodic techno producer and composer. He released his first EP, Traque, on Basilic Records in 2008 under the name N'to, then co-founded the Hungry Music collective and label with Worakls and Joachim Pastor in 2013. He left Hungry Music in 2020 and released the album Apnea on AllPoints in 2021, followed by Forever Friends with pianist Sofiane Pamart in 2024." }, origin: "Marseille, France", since: 2008, labels: ["Hungry Music", "AllPoints"], sources: ["https://en.wikipedia.org/wiki/NTO_(musician)", "https://en.wikipedia.org/wiki/Hungry_Music"] }, // NTO
  "oklou": { slug: "oklou", bio: { fr: "Marylou Mayniel, née en 1993 à Poitiers, compose sous le nom d'Oklou une pop électronique bâtie sur boîtes à rythmes, synthétiseurs et nappes d'ambiance, après une formation classique au piano et au violoncelle. Elle cofonde en 2015 le collectif de DJ féminin TGAF et publie son EP « The Rite of May » sur le label londonien NUXXE en 2018. Sa mixtape « Galore » paraît en 2020 et son premier album, « choke enough », en 2025.", en: "Born in Poitiers in 1993, Marylou Mayniel writes electronic pop as Oklou, built on drum machines, synthesisers and ambient textures, after classical training on piano and cello. She co-founded the all-female DJ collective TGAF in 2015 and released her EP \"The Rite of May\" on London label NUXXE in 2018. Her mixtape \"Galore\" appeared in 2020 and her first album, \"choke enough\", in 2025." }, origin: "Poitiers, France", since: 2014, labels: ["NUXXE"], sources: ["https://en.wikipedia.org/wiki/Oklou", "https://fr.wikipedia.org/wiki/Oklou"], photo: { file: "oklou.webp", author: "Blaithnaid", license: "CC0", page: "https://commons.wikimedia.org/wiki/File:Oklou_performing_in_the_Academy_in_2025.jpg" } }, // Oklou
  "onlynumbers": { slug: "onlynumbers", bio: { fr: "Onlynumbers, de son vrai nom Tom Cillio Bosgiraud, est un producteur et DJ français originaire de Lyon, aujourd'hui installé en Tchéquie. Il joue une hard techno rapide et très travaillée en sound design, qu'il décrit lui-même comme « euphorique, profonde et chaotique, avec des sous-textes cinématographiques ». Il compose entièrement sur ordinateur, sous FL Studio, et s'est imposé sur le circuit européen des festivals à partir de fin 2023.", en: "Onlynumbers, real name Tom Cillio Bosgiraud, is a French producer and DJ from Lyon, now based in Czechia. He plays fast, sound-design-heavy hard techno that he describes himself as \"euphoric, deep and chaotic with cinematic undertones\". He produces entirely in the box, in FL Studio, and broke onto the European festival circuit from late 2023." }, origin: "Lyon, France", sources: ["https://technomusicworld.com/artist/onlynumbers/about", "https://www.trueunderground.one/chaos-beauty-cinematic-techno-the-mind-of-onlynumbers-unveiled/"] }, // Onlynumbers
  "ophidian": { slug: "ophidian", bio: { fr: "Conrad Hoyer, né en 1981 à Arnhem, produit du hardcore et du darkcore aux Pays-Bas depuis 1998. Longtemps signé sur Enzyme Records, il a monté les sous-labels Meta4 et Meta0, ce dernier sous son alias Meander. Ses albums Blackbox (2003), le double Betrayed By Daylight (2005) et Call Of The Void (2021) explorent des tempos plus lents et des textures industrielles.", en: "Conrad Hoyer, born in 1981 in Arnhem, has been making hardcore and darkcore in the Netherlands since 1998. Long signed to Enzyme Records, he set up the Meta4 and Meta0 sub-labels, the latter under his Meander alias. His albums Blackbox (2003), the double Betrayed By Daylight (2005) and Call Of The Void (2021) explore slower tempos and industrial textures." }, origin: "Arnhem, Pays-Bas", since: 1998, labels: ["Enzyme Records", "Meta4"], sources: ["https://nl.wikipedia.org/wiki/Ophidian"], photo: { file: "ophidian.webp", author: "Imar van den Berg", license: "CC BY 3.0", page: "https://commons.wikimedia.org/wiki/File:Ophidian.jpg" } }, // Ophidian
  "oscar-mulero": { slug: "oscar-mulero", bio: { fr: "Óscar Mulero Crecente est un DJ et producteur de techno madrilène. Il commence à mixer à la fin des années 1980 dans des clubs de Madrid comme le New World et l'Overdrive, puis ouvre en 1994 son propre club, The Omen. Il dirige deux labels : Warm Up Recordings, lancé en 2000, et PoleGroup Recordings, lancé en 2004, qui comptent chacun plus de cent références. Son album Black Propaganda est paru en 2012.", en: "Óscar Mulero Crecente is a techno DJ and producer from Madrid. He began playing in Madrid clubs such as New World and Overdrive in the late 1980s, then opened his own venue, The Omen, in 1994. He runs two labels: Warm Up Recordings, started in 2000, and PoleGroup Recordings, started in 2004, each with more than a hundred releases. His album Black Propaganda came out in 2012." }, origin: "Madrid, Espagne", labels: ["PoleGroup Recordings", "Warm Up Recordings"], sources: ["https://en.wikipedia.org/wiki/Oscar_Mulero"] }, // Oscar Mulero
  "overmono": { slug: "overmono", bio: { fr: "Overmono est un duo gallois de musique électronique formé par les frères Tom et Ed Russell, actifs auparavant en solo sous les alias Truss et Tessela. Ils produisent ensemble depuis 2015 et sortent leur premier EP, Arla, sur XL Recordings en 2016, en parallèle de leur label Poly Kicks. Leur premier album, Good Lies, paraît en mai 2023 chez XL et atteint la 11e place des classements britanniques.", en: "Overmono are a Welsh electronic duo formed by brothers Tom and Ed Russell, previously active solo as Truss and Tessela. They have produced together since 2015 and released their first EP, Arla, on XL Recordings in 2016, alongside their own label Poly Kicks. Their debut album, Good Lies, came out on XL in May 2023 and reached number 11 on the UK Albums Chart." }, origin: "Pays de Galles, Royaume-Uni", since: 2015, labels: ["XL Recordings", "Poly Kicks"], sources: ["https://en.wikipedia.org/wiki/Overmono"] }, // Overmono
  "pan-pot": { slug: "pan-pot", bio: { fr: "Pan-Pot est un duo techno berlinois composé de Tassilo Ippenberger et Thomas Benedix. Ils se rencontrent en 2003 au SAE Institute de Berlin, où ils étudient l'ingénierie du son, et se lancent en 2005 avec le maxi « Copy and Paste » sur le label Mobilee d'Anja Schneider. Leur premier album, Pan-O-Rama, sort en 2007. En 2014, ils créent le label Second State, sur lequel ils signent Amelie Lens.", en: "Pan-Pot is a Berlin techno duo made up of Tassilo Ippenberger and Thomas Benedix. They met in 2003 at Berlin's SAE Institute, where they studied audio engineering, and started out in 2005 with the single \"Copy and Paste\" on Anja Schneider's Mobilee label. Their first album, Pan-O-Rama, appeared in 2007. In 2014 they launched the label Second State, where they signed Amelie Lens." }, origin: "Berlin, Allemagne", since: 2005, labels: ["Second State", "Mobilee"], sources: ["https://en.wikipedia.org/wiki/Pan-Pot"], photo: { file: "pan-pot.webp", author: "Robin Krahl", license: "CC BY-SA 4.0", page: "https://commons.wikimedia.org/wiki/File:2015-07-19_6705_Pan-Pot_(Sea_You).jpg" } }, // Pan-Pot
  "paul-elstak": { slug: "paul-elstak", bio: { fr: "Paul Roger Elstak, connu sous le nom de DJ Paul Elstak, est un DJ, producteur et patron de label néerlandais né à La Haye en 1966. Il a fondé en 1992 Rotterdam Records, premier label hardcore des Pays-Bas, puis Offensive Records en 2001. Ses tubes happy hardcore de 1995-1996, « Luv U More » et « Rainbow in the Sky », se sont classés respectivement 2e et 3e du Top 40 néerlandais. Il a coproduit « Europapa », la chanson des Pays-Bas à l'Eurovision 2024, et reçu le Gouden Harp en 2023.", en: "Paul Roger Elstak, known as DJ Paul Elstak, is a Dutch DJ, producer and label owner born in The Hague in 1966. In 1992 he founded Rotterdam Records, the first hardcore label in the Netherlands, then Offensive Records in 2001. His 1995–96 happy hardcore hits \"Luv U More\" and \"Rainbow in the Sky\" reached number 2 and number 3 in the Dutch Top 40. He co-produced \"Europapa\", the Netherlands' 2024 Eurovision entry, and received the Gouden Harp award in 2023." }, origin: "La Haye, Pays-Bas", since: 1992, labels: ["Rotterdam Records", "Offensive Records"], sources: ["https://nl.wikipedia.org/wiki/Paul_Elstak"], photo: { file: "paul-elstak.webp", author: "Kristel van den Hooven", license: "CC BY 3.0", page: "https://commons.wikimedia.org/wiki/File:Dj-paul-elstak-1305292754.jpg" } }, // Paul Elstak
  "paul-kalkbrenner": { slug: "paul-kalkbrenner", bio: { fr: "Paul Kalkbrenner, né le 11 juin 1977, est un musicien et producteur allemand qui a grandi à Lichtenberg, dans l'ancien Berlin-Est. Il joue en live plutôt qu'en DJ set, en recomposant ses morceaux élément par élément sur scène. Il a publié ses premiers disques sur BPitch Control à partir de 1999 sous le nom de Paul dB+, puis a tenu le rôle d'Ickarus dans le film Berlin Calling (2008), dont il signe la bande originale et le titre « Sky and Sand », chanté par son frère Fritz Kalkbrenner.", en: "Paul Kalkbrenner, born 11 June 1977, is a German musician and producer who grew up in Lichtenberg, in what was then East Berlin. He performs live rather than as a DJ, rebuilding his tracks element by element on stage. He put out his first records on BPitch Control from 1999 under the name Paul dB+, then played Ickarus in the film Berlin Calling (2008), for which he wrote the soundtrack and the track \"Sky and Sand\", sung by his brother Fritz Kalkbrenner." }, origin: "Berlin, Allemagne", since: 1999, labels: ["BPitch Control"], sources: ["https://en.wikipedia.org/wiki/Paul_Kalkbrenner"], photo: { file: "paul-kalkbrenner.webp", author: "pitpony.photography", license: "CC BY-SA 3.0", page: "https://commons.wikimedia.org/wiki/File:Paul_Kalkbrenner_2016_(1_von_3)_(cropped).jpg" } }, // Paul Kalkbrenner
  "peggy-gou": { slug: "peggy-gou", bio: { fr: "Kim Min-ji, née en 1991 en Corée du Sud et installée à Berlin, mixe et produit sous le nom de Peggy Gou, entre house et techno. Elle a publié sept EP, notamment sur Ninja Tune et Phonica, puis fondé son propre label Gudu Records en 2019 et mixé un volume de la série DJ-Kicks pour !K7. Son premier album, « I Hear You », est sorti en juin 2024 chez XL Recordings.", en: "Born in South Korea in 1991 and based in Berlin, Kim Min-ji DJs and produces as Peggy Gou, working between house and techno. She has released seven EPs, notably on Ninja Tune and Phonica, then founded her own label Gudu Records in 2019 and mixed a volume of the DJ-Kicks series for !K7. Her debut album \"I Hear You\" came out in June 2024 on XL Recordings." }, origin: "Corée du Sud", labels: ["Gudu Records", "Ninja Tune"], sources: ["https://en.wikipedia.org/wiki/Peggy_Gou"], photo: { file: "peggy-gou.webp", author: "Davide Guidone", license: "Public domain", page: "https://commons.wikimedia.org/wiki/File:Peggy_Gou_2019.jpg" } }, // Peggy Gou
  "petit-biscuit": { slug: "petit-biscuit", bio: { fr: "Mehdi Benjelloun, alias Petit Biscuit, est un producteur et multi-instrumentiste français né en 1999 à Rouen. Il se fait connaître à seize ans avec le single « Sunset Lover » (2015), qui mêle guitare acoustique, textures électroniques et voix retravaillées, entre deep house et downtempo. Pour rester indépendant, il monte son propre label, Petit Biscuit Music, sur lequel paraissent les albums Presence (2017), Parachute (2020) et Discipline (2024).", en: "Mehdi Benjelloun, who records as Petit Biscuit, is a French producer and multi-instrumentalist born in Rouen in 1999. He broke through at sixteen with the single \"Sunset Lover\" (2015), layering acoustic guitar, electronic textures and treated vocals somewhere between deep house and downtempo. To stay independent he set up his own label, Petit Biscuit Music, home to the albums Presence (2017), Parachute (2020) and Discipline (2024)." }, origin: "Rouen, France", since: 2015, labels: ["Petit Biscuit Music"], sources: ["https://en.wikipedia.org/wiki/Petit_Biscuit", "https://fr.wikipedia.org/wiki/Petit_Biscuit"] }, // Petit Biscuit
  "planetary-assault-systems": { slug: "planetary-assault-systems", bio: { fr: "Planetary Assault Systems est le principal alias de Luke Slater, musicien et producteur anglais né en 1968 à Reading, qui se consacre à la techno depuis le début des années 1990. Sous ce nom, il défend une techno de club dépouillée et physique, notamment sur l'album The Messenger (2011) publié par Ostgut Ton. Il dirige aussi son propre label, Mote-Evolver, lancé en 2006, et enregistre par ailleurs sous les noms The 7th Plain et L.B. Dub Corp.", en: "Planetary Assault Systems is the main alias of Luke Slater, an English musician and producer born in Reading in 1968 who has focused on techno since the early 1990s. Under that name he makes stripped-back, physical club techno, notably on the album The Messenger (2011), released by Ostgut Ton. He also runs his own label, Mote-Evolver, launched in 2006, and records as The 7th Plain and L.B. Dub Corp." }, origin: "Reading, Royaume-Uni", since: 1993, labels: ["Mote-Evolver", "Ostgut Ton", "Peacefrog Records"], sources: ["https://en.wikipedia.org/wiki/Luke_Slater"], photo: { file: "planetary-assault-systems.webp", author: "PASLBDUB", license: "CC BY-SA 4.0", page: "https://commons.wikimedia.org/wiki/File:Luke_Slater_1_24.jpg" } }, // Planetary Assault Systems
  "prospa": { slug: "prospa", bio: { fr: "Duo britannique formé par Harvey Blumler et Gosha Smith, amis d'enfance originaires de Leeds, Prospa produit ensemble depuis 2013 une house nourrie de rave et de breakbeat. Leur morceau « Prayer » (2018) est choisi par Annie Mac comme Hottest Record in the World sur BBC Radio 1. Après des sorties sur Circoloco Records, le duo a lancé son propre label, Rave Science, distribué par Polydor.", en: "A British duo made up of Harvey Blumler and Gosha Smith, childhood friends from Leeds, Prospa have been producing together since 2013, blending house with rave and breakbeat. Their track \"Prayer\" (2018) was picked by Annie Mac as Hottest Record in the World on BBC Radio 1. After releasing on Circoloco Records, the pair launched their own label, Rave Science, through Polydor." }, origin: "Leeds, Angleterre", since: 2013, labels: ["Rave Science", "Circoloco Records"], sources: ["https://en.wikipedia.org/wiki/Prospa"] }, // Prospa
  "quelza": { slug: "quelza", bio: { fr: "Quelza est le nom de scène de Léo Naït Aïssa, producteur et DJ français installé à Berlin. Il façonne une techno hypnotique où se glissent des breakbeats et des textures proches de l'IDM, dans un travail sonore souvent décrit comme cinématographique. Ses disques sont sortis sur le label 47 de Tommy Four Seven, sur Hayes Collective, Mord, Kuboraum Editions et sur la série UFO de Dekmantel.", en: "Quelza is the stage name of Léo Naït Aïssa, a French producer and DJ based in Berlin. He builds hypnotic techno laced with breakbeats and IDM-leaning textures, in a sound design frequently described as cinematic. His records have appeared on Tommy Four Seven's 47 imprint, Hayes Collective, Mord, Kuboraum Editions and Dekmantel's UFO series." }, origin: "France, installé à Berlin", labels: ["47", "Hayes Collective", "Dekmantel"], sources: ["https://mixmagde.com/read/french-techno-innovator-quelza-debuts-on-dekmantels-ufo-series-music", "https://www.nts.live/artists/120723-quelza"] }, // Quelza
  "r3hab": { slug: "r3hab", bio: { fr: "R3HAB est le nom de scène de Fadil El Ghoul, né le 2 avril 1986, DJ et producteur néerlandais d'origine marocaine. Il débute fin 2007 avec le morceau « Mrkrstft », remixé par son compatriote de Breda Hardwell, puis signe chez le label d'Afrojack après « Prutataaa ». Il dirige son propre label, CYB3RPVNK, a publié les albums Trouble (2017) et The Wave (2018), et a atteint la 12e place du Top 100 DJs de DJ Mag en 2018.", en: "R3HAB is the stage name of Fadil El Ghoul, born 2 April 1986, a Dutch-Moroccan DJ and producer. He started out in late 2007 with the track \"Mrkrstft\", remixed by fellow Breda DJ Hardwell, then signed to Afrojack's label after \"Prutataaa\". He runs his own imprint CYB3RPVNK, released the albums Trouble (2017) and The Wave (2018), and reached number 12 in DJ Mag's Top 100 DJs in 2018." }, origin: "Breda, Pays-Bas", since: 2007, labels: ["CYB3RPVNK"], sources: ["https://en.wikipedia.org/wiki/R3hab"], photo: { file: "r3hab.webp", author: "Wingolinek", license: "CC BY-SA 4.0", page: "https://commons.wikimedia.org/wiki/File:R3HAB_BTS.jpg" } }, // R3HAB
  "rampa": { slug: "rampa", bio: { fr: "DJ et producteur allemand, membre fondateur du collectif et label berlinois Keinemusik, lancé en 2009 avec Adam Port, &ME, Reznik et Monja Gentschow. Sa house et sa techno reposent sur des percussions très présentes, souvent d'inspiration africaine, et il a sorti sur Innervisions, Diynamic ou Cocoon. Il a coproduit deux morceaux de l'album Honestly, Nevermind de Drake (2022) et monté TEILE, qui fabrique des effets analogiques pour DJ.", en: "German DJ and producer, a founding member of the Berlin collective and label Keinemusik, launched in 2009 with Adam Port, &ME, Reznik and Monja Gentschow. His house and techno lean on prominent, often African-inflected percussion, and he has released on Innervisions, Diynamic and Cocoon. He co-produced two tracks on Drake's album Honestly, Nevermind (2022) and set up TEILE, which builds analogue effects for DJs." }, origin: "Berlin, Allemagne", since: 2009, labels: ["Keinemusik"], sources: ["https://en.wikipedia.org/wiki/Keinemusik", "https://keinemusik.com/crue/rampa/"] }, // Rampa
  "rdhad": { slug: "rdhad", bio: { fr: "Mike Bierbach, né en 1984 et originaire de Berlin-Est, joue une techno sombre et tendue, souvent jouée lentement. Il a cofondé Dystopian en 2009, d'abord une série de soirées berlinoises devenue un label, et compte parmi les DJ réguliers du Berghain. Il a publié l'album Anxious (2017) ainsi que des disques avec Vril et JakoJako.", en: "Mike Bierbach, born in 1984 and raised in East Berlin, plays dark, taut techno, often at slow tempos. In 2009 he co-founded Dystopian, first a Berlin party series that became a record label, and he is a regular behind the decks at Berghain. He released the album Anxious (2017) as well as records with Vril and JakoJako." }, origin: "Berlin, Allemagne", since: 2009, labels: ["Dystopian"], sources: ["https://en.wikipedia.org/wiki/R%C3%B8dh%C3%A5d"] }, // Rødhåd
  "richie-hawtin": { slug: "richie-hawtin", bio: { fr: "Né en 1970 à Banbury en Angleterre et élevé à LaSalle, près de Windsor en Ontario, Richie Hawtin participe à la deuxième vague de la techno de Detroit au début des années 1990 et devient une référence de la techno minimale. Il enregistre sous les alias Plastikman et F.U.S.E., dont l'album « Dimension Intrusion » (1993) paraît dans la série Artificial Intelligence de Warp. Il cofonde le label Plus 8 avec John Acquaviva en 1990, lance M-nus en 1998, tient la soirée ENTER. au Space d'Ibiza de 2012 à 2015 et conçoit en 2016 la table de mixage MODEL 1.", en: "Born in Banbury, England in 1970 and raised in LaSalle, near Windsor, Ontario, Richie Hawtin took part in Detroit techno's second wave in the early 1990s and became a leading minimal techno figure. He records as Plastikman and F.U.S.E., the latter's album \"Dimension Intrusion\" (1993) appearing in Warp's Artificial Intelligence series. He co-founded the Plus 8 label with John Acquaviva in 1990, launched M-nus in 1998, ran the weekly ENTER. party at Space in Ibiza from 2012 to 2015, and designed the MODEL 1 mixer in 2016." }, origin: "Windsor, Canada", since: 1990, labels: ["Plus 8", "M-nus"], sources: ["https://en.wikipedia.org/wiki/Richie_Hawtin"], photo: { file: "richie-hawtin.webp", author: "Knöre", license: "CC BY-SA 4.0", page: "https://commons.wikimedia.org/wiki/File:Richie_Hawtin_-_SMS_2018.jpg" } }, // Richie Hawtin
  "roza-terenzi": { slug: "roza-terenzi", bio: { fr: "Roza Terenzi est l'alias de Katie Campbell, DJ et productrice australienne originaire de Perth, installée à Melbourne depuis 2017. Formée à la Western Australian Academy of the Performing Arts, elle a d'abord produit sous le nom de Catlips avant d'adopter en 2016 ce pseudonyme emprunté à l'astrophysicienne et musicienne italienne Fiorella Terenzi. Son premier album, Modern Bliss, est sorti en 2020.", en: "Roza Terenzi is the alias of Katie Campbell, an Australian DJ and producer originally from Perth who moved to Melbourne in 2017. Trained at the Western Australian Academy of the Performing Arts, she first produced as Catlips before taking on this name in 2016, borrowed from the Italian astrophysicist and musician Fiorella Terenzi. Her debut album, Modern Bliss, came out in 2020." }, origin: "Perth, Australie", since: 2016, sources: ["https://en.wikipedia.org/wiki/Roza_Terenzi"] }, // Roza Terenzi
  "sara-landry": { slug: "sara-landry", bio: { fr: "Sara Landry, née le 22 septembre 1993 à Sausalito en Californie, est une DJ et productrice américaine installée à Amsterdam depuis 2022. Elle joue une hard techno industrielle sombre et se présente comme productrice et ingénieure du son autodidacte. En juillet 2021, elle a fondé son label Hekate Records, qui publie notamment Nico Moreno, Shlømo et Charlie Sparks. Elle est entrée au Top 100 DJs de DJ Mag en 2024, à la 75e place.", en: "Sara Landry, born 22 September 1993 in Sausalito, California, is an American DJ and producer who has been based in Amsterdam since 2022. She plays dark, industrial hard techno and describes herself as a self-taught producer and audio engineer. In July 2021 she founded her label Hekate Records, which releases artists including Nico Moreno, Shlømo and Charlie Sparks. She entered DJ Mag's Top 100 DJs at number 75 in 2024." }, origin: "Sausalito, États-Unis", since: 2018, labels: ["Hekate Records"], sources: ["https://en.wikipedia.org/wiki/Sara_Landry"], photo: { file: "sara-landry.webp", author: "Stormedelf", license: "CC BY 4.0", page: "https://commons.wikimedia.org/wiki/File:Sara_Landry_Palace_of_Fine_Arts_SF_11-28-2025.jpg" } }, // Sara Landry
  "scooter": { slug: "scooter", bio: { fr: "Groupe allemand formé à Hambourg en 1993 autour du chanteur H. P. Baxxter, passé de la techno hardcore à la happy hardcore et à l'eurodance. « Hyper Hyper » (1994), « How Much Is the Fish? » et « Nessaja » comptent parmi ses succès, pour plus de 30 millions de disques vendus. Le groupe découpe sa carrière en « chapitres », le septième ayant débuté fin 2022.", en: "German band formed in Hamburg in 1993 around singer H. P. Baxxter, moving from hardcore techno into happy hardcore and Eurodance. \"Hyper Hyper\" (1994), \"How Much Is the Fish?\" and \"Nessaja\" are among their hits, for over 30 million records sold. The band splits its career into \"chapters\", the seventh of which began in late 2022." }, origin: "Hambourg, Allemagne", since: 1993, labels: ["Sheffield Tunes"], sources: ["https://en.wikipedia.org/wiki/Scooter_(band)"], photo: { file: "scooter.webp", author: "Stefan Brending (2eight)", license: "CC BY-SA 4.0", page: "https://commons.wikimedia.org/wiki/File:2022_Rock_im_Park_-_Scooter_-_H_P_Baxxter_-_by_2eight_-_9SC7035.jpg" } }, // Scooter
  "serafina": { slug: "serafina", bio: { fr: "Serafina est une DJ allemande basée à Hambourg, où elle a commencé à mixer en 2023. Elle a d'abord joué une techno industrielle très frontale, portée par des basses lourdes, avant d'élargir ses sets à un versant plus rapide et mélodique. Elle tourne depuis sur le circuit européen, notamment pour Awakenings.", en: "Serafina is a German DJ based in Hamburg, where she started playing out in 2023. She built her sets on blunt, bass-heavy industrial techno before widening them towards a faster, more melodic register. She now works the European circuit, including for Awakenings." }, origin: "Hambourg, Allemagne", since: 2023, sources: ["https://framedagency.au/artists/serafina", "https://www.awakenings.com/en/artists/serafina/386088/"] }, // Serafina
  "sigma": { slug: "sigma", bio: { fr: "Sigma est un duo britannique de drum and bass formé en 2007 par Cameron Edwards et Joe Lenzie, qui se sont rencontrés à l'université de Leeds lors de soirées drum and bass avant de s'installer à Londres. Après des sorties sur Hospital Records et Breakbeat Kaos, leur signature chez 3 Beat Records en 2013 les a menés à deux numéros un consécutifs au Royaume-Uni : « Nobody to Love » puis « Changing » avec Paloma Faith, tous deux en 2014. Ont suivi « Higher » avec Labrinth et « Glitterball » avec Ella Henderson en 2015.", en: "Sigma are a British drum and bass duo formed in 2007 by Cameron Edwards and Joe Lenzie, who met at drum and bass nights while studying at Leeds University before moving to London. After releases on Hospital Records and Breakbeat Kaos, signing to 3 Beat Records in 2013 took them to two consecutive UK number ones: \"Nobody to Love\" and then \"Changing\" with Paloma Faith, both in 2014. \"Higher\" with Labrinth and \"Glitterball\" with Ella Henderson followed in 2015." }, origin: "Harpenden, Royaume-Uni", since: 2007, labels: ["3 Beat Records", "Hospital Records"], sources: ["https://en.wikipedia.org/wiki/Sigma_(group)"] }, // Sigma
  "skrillex": { slug: "skrillex", bio: { fr: "Sonny Moore, né en 1988 à Los Angeles, a d'abord chanté dans le groupe post-hardcore From First to Last avant d'adopter l'alias Skrillex en 2008. Son dubstep saturé, lancé par l'EP Scary Monsters and Nice Sprites (2010) puis Bangarang (2011), lui a valu neuf Grammy Awards. Il a fondé le label OWSLA en 2011 et publié en 2023 les albums Quest for Fire et Don't Get Too Close.", en: "Sonny Moore, born in Los Angeles in 1988, first sang in the post-hardcore band From First to Last before taking the Skrillex alias in 2008. His saturated dubstep, launched by the EP Scary Monsters and Nice Sprites (2010) then Bangarang (2011), has earned him nine Grammy Awards. He founded the OWSLA label in 2011 and released the albums Quest for Fire and Don't Get Too Close in 2023." }, origin: "Los Angeles, États-Unis", since: 2008, labels: ["OWSLA"], sources: ["https://en.wikipedia.org/wiki/Skrillex"], photo: { file: "skrillex.webp", author: "Sean Phillips", license: "CC BY 2.0", page: "https://commons.wikimedia.org/wiki/File:Skrillex_-_1.jpg" } }, // Skrillex
  "solomun": { slug: "solomun", bio: { fr: "Mladen Solomun, connu sous le nom de Solomun, est un DJ et producteur bosno-allemand né le 27 décembre 1975 à Travnik et élevé à Hambourg. Il fonde fin 2005 le label Diynamic avec Adriano Trolio, puis le label plus expérimental 2DIY4 en 2010. Son remix d'Around de Noir & Haze, sorti en 2011, a été élu meilleur remix de l'année par Resident Advisor.", en: "Mladen Solomun, known as Solomun, is a Bosnian-German DJ and producer born on 27 December 1975 in Travnik and raised in Hamburg. He founded the Diynamic label with Adriano Trolio at the end of 2005, then the more experimental 2DIY4 in 2010. His 2011 remix of Noir & Haze's \"Around\" was voted remix of the year by Resident Advisor." }, origin: "Travnik, Bosnie-Herzégovine / Hambourg, Allemagne", since: 2005, labels: ["Diynamic", "2DIY4"], sources: ["https://fr.wikipedia.org/wiki/Solomun", "https://en.wikipedia.org/wiki/Solomun_(musician)"] }, // Solomun
  "sonny-fodera": { slug: "sonny-fodera", bio: { fr: "DJ et producteur house australien né à Adélaïde en 1985, installé à Londres. Venu à la house après avoir vu jouer Derrick Carter en club, il a sorti sur Defected et Cajual avant de fonder son propre label Solotoko début 2017. « One Night » avec MK (2019) et « Somedays » avec Jazzy et D.O.D. (2025) figurent parmi ses titres certifiés au Royaume-Uni.", en: "Australian house DJ and producer, born in Adelaide in 1985 and based in London. He turned to house after seeing Derrick Carter play in a club, released on Defected and Cajual, then founded his own Solotoko label in early 2017. \"One Night\" with MK (2019) and \"Somedays\" with Jazzy and D.O.D. (2025) are among his UK-certified tracks." }, origin: "Adélaïde, Australie", labels: ["Solotoko", "Defected"], sources: ["https://en.wikipedia.org/wiki/Sonny_Fodera"] }, // Sonny Fodera
  "space-92": { slug: "space-92", bio: { fr: "Space 92 est le projet techno de Mathieu Mourareau, producteur français qui a grandi à Carcassonne. Après une dizaine d'années sous le nom Matt Minimal, il lance Space 92 en 2019 avec « Another Galaxy » : une techno mélodique et trancey, percussions saturées et nappes de synthé nourries de science-fiction des années 1980. « Planet X », avec The YellowHeads, est resté sept semaines en tête du classement techno de Beatport, où il fut l'artiste techno le plus vendu de 2020.", en: "Space 92 is the techno project of Mathieu Mourareau, a French producer who grew up in Carcassonne. After roughly a decade as Matt Minimal, he launched Space 92 in 2019 with \"Another Galaxy\": melodic, trance-leaning techno with distorted percussion and synth pads fed by 1980s science fiction. \"Planet X\", with The YellowHeads, spent seven weeks at number one on Beatport's techno chart, where he was the best-selling techno artist of 2020." }, origin: "Carcassonne, France", since: 2019, labels: ["Perfekt Groove Recordings", "Filth On Acid", "1605"], sources: ["https://www.beatportal.com/articles/12120-introducing-space-92-technos-new-cosmic-champion"] }, // Space 92
  "stef-davidse": { slug: "stef-davidse", bio: { fr: "Stef Davidse est un DJ et producteur néerlandais basé à Rotterdam, venu du hip-hop avant de découvrir la house en 2018. Sa musique garde cet héritage : basses roulantes, groove tech house et voix soul. Il publie sur No Art, WYLD Records, Micro Hertz et Eastenderz, le label d'East End Dubs, et sa collaboration « Burnin » avec ANOTR dépasse les deux millions d'écoutes sur Spotify.", en: "Stef Davidse is a Dutch DJ and producer based in Rotterdam who came from hip-hop before discovering house in 2018. That background still shows: rolling basslines, tech house groove and soulful vocals. He releases on No Art, WYLD Records, Micro Hertz and Eastenderz, East End Dubs' label, and his collaboration \"Burnin\" with ANOTR has passed two million Spotify streams." }, origin: "Rotterdam, Pays-Bas", since: 2018, labels: ["No Art", "WYLD Records", "Eastenderz"], sources: ["https://grayarea.co/magazine/press-play-on-stef-davidse-rotterdam-s-rising-house-star"] }, // Stef Davidse
  "steve-aoki": { slug: "steve-aoki", bio: { fr: "DJ et producteur américain né en 1977, Steve Aoki a fondé son label Dim Mak Records en 1996, qui a publié MSTRKRFT, The Bloody Beetroots, Bloc Party ou Klaxons. Son premier album, « Wonderland » (2012), a été nommé au Grammy du meilleur album dance/électronique en 2013, et Pollstar l'a désigné en 2012 comme l'artiste EDM générant le plus de recettes de tournée en Amérique du Nord. Il a signé sept albums studio et publié en 2019 un livre de mémoires, « Blue: The Color of Noise ».", en: "An American DJ and producer born in 1977, Steve Aoki founded his label Dim Mak Records in 1996, releasing MSTRKRFT, The Bloody Beetroots, Bloc Party and Klaxons among others. His first album \"Wonderland\" (2012) was nominated for the Grammy for Best Dance/Electronica Album in 2013, and Pollstar named him the highest-grossing EDM touring artist in North America in 2012. He has released seven studio albums and published a memoir, \"Blue: The Color of Noise\", in 2019." }, origin: "États-Unis", since: 1996, labels: ["Dim Mak Records"], sources: ["https://en.wikipedia.org/wiki/Steve_Aoki"], photo: { file: "steve-aoki.webp", author: "Gage Skidmore", license: "CC BY-SA 3.0", page: "https://commons.wikimedia.org/wiki/File:Steve_Aoki_by_Gage_Skidmore.jpg" } }, // Steve Aoki
  "sven-vath": { slug: "sven-vath", bio: { fr: "Né en 1964 à Obertshausen, près de Francfort, il ouvre le club Omen en 1988 et fonde successivement les labels Eye Q (1991), Harthouse (1992) puis Cocoon Recordings (1999). Sa techno traversée de trance et d'ambient s'entend sur l'album Accident in Paradise (1992). Il a tenu la résidence Cocoon du lundi soir à l'Amnesia d'Ibiza de 1999 à 2018.", en: "Born in 1964 in Obertshausen, near Frankfurt, he opened the Omen club in 1988 and founded the labels Eye Q (1991), Harthouse (1992) and then Cocoon Recordings (1999). His techno, run through with trance and ambient, is heard on the album Accident in Paradise (1992). He held the Monday-night Cocoon residency at Amnesia in Ibiza from 1999 to 2018." }, origin: "Obertshausen, Allemagne", since: 1986, labels: ["Cocoon Recordings", "Harthouse", "Eye Q Records"], sources: ["https://en.wikipedia.org/wiki/Sven_V%C3%A4th"], photo: { file: "sven-vath.webp", author: "Krd", license: "CC BY-SA 3.0", page: "https://commons.wikimedia.org/wiki/File:Sven_V%C3%A4th_01.jpg" } }, // Sven Väth
  "teho": { slug: "teho", bio: { fr: "Teho, de son vrai nom Théo Vicente, est un producteur et DJ français installé à Montpellier, actif dans la techno mélodique. Il se fait connaître par des sorties sur Parquet Recordings et Traum Schallplatten, puis fonde en novembre 2016 son propre label, Labo T., conçu comme un laboratoire sonore ouvert à plusieurs genres. Il a notamment publié les albums Infinity en 2022 et Shifting en 2024.", en: "Teho, real name Théo Vicente, is a French producer and DJ based in Montpellier, working in melodic techno. He first drew attention with releases on Parquet Recordings and Traum Schallplatten, then founded his own label, Labo T., in November 2016, conceived as a sound laboratory open to several genres. His albums include Infinity in 2022 and Shifting in 2024." }, origin: "Montpellier, France", labels: ["Labo T.", "Traum Schallplatten"], sources: ["https://electronicgroove.com/artist-profile-teho/", "https://www.discogs.com/artist/1457615"] }, // Teho
  "the-avalanches": { slug: "the-avalanches", bio: { fr: "The Avalanches est un groupe électronique australien formé à Melbourne en 1997, aujourd'hui composé de Robbie Chater et Tony Di Blasi, membres fondateurs, et du multi-instrumentiste Andy Szekeres. Ils pratiquent le plunderphonics, une musique entièrement bâtie à partir de disques échantillonnés, et leur premier album Since I Left You (2000) en est considéré comme une référence. Ont suivi Wildflower (2016) et We Will Always Love You (2020). Sur scène, ils mêlent jeu live et DJing.", en: "The Avalanches are an Australian electronic group formed in Melbourne in 1997, now made up of founding members Robbie Chater and Tony Di Blasi plus multi-instrumentalist Andy Szekeres. They work in plunderphonics, music built entirely from sampled records, and their first album Since I Left You (2000) is widely treated as a benchmark of the genre. Wildflower (2016) and We Will Always Love You (2020) followed. On stage they combine live playing with DJing." }, origin: "Melbourne, Australie", since: 1997, labels: ["Modular Recordings", "XL Recordings"], sources: ["https://en.wikipedia.org/wiki/The_Avalanches"], photo: { file: "the-avalanches.webp", author: "Raph_PH", license: "CC BY 2.0", page: "https://commons.wikimedia.org/wiki/File:StrokesRosendal080622-2_(52144817677).jpg" } }, // The Avalanches
  "tiesto": { slug: "tiesto", bio: { fr: "Tijs Verwest, né en 1969 à Breda aux Pays-Bas, a commencé à mixer dans les clubs néerlandais dès le milieu des années 1980 avant de fonder en 1997 le label Black Hole Recordings avec Arny Bink. Son premier album solo, « In My Memory » (2001), et son remix de « Silence » de Delerium l'ont fait connaître au grand public ; il a été élu meilleur DJ du monde par DJ Mag trois années de suite, de 2002 à 2004. En 2004, il est devenu le premier DJ à jouer sur scène lors d'une cérémonie d'ouverture olympique, à Athènes.", en: "Born in Breda, the Netherlands in 1969, Tijs Verwest began DJing in Dutch clubs in the mid-1980s before founding the Black Hole Recordings label with Arny Bink in 1997. His first solo album \"In My Memory\" (2001) and his remix of Delerium's \"Silence\" brought him to a wider audience; DJ Mag readers voted him world number one DJ three years running, from 2002 to 2004. In 2004 he became the first DJ to play live on stage at an Olympic opening ceremony, in Athens." }, origin: "Breda, Pays-Bas", labels: ["Black Hole Recordings"], sources: ["https://en.wikipedia.org/wiki/Ti%C3%ABsto"], photo: { file: "tiesto.webp", author: "Julia Keiser", license: "CC BY-SA 4.0", page: "https://commons.wikimedia.org/wiki/File:Ti%C3%ABsto_@_Airbeat_One_2017.jpg" } }, // Tiësto
  "underworld": { slug: "underworld", bio: { fr: "Groupe électronique britannique formé en 1987, né de la rencontre de Karl Hyde et Rick Smith à Cardiff. Leur techno progressive mêlée de spoken word s'impose avec l'album Dubnobasswithmyheadman (1994), puis avec « Born Slippy .NUXX », porté par la bande originale de Trainspotting en 1996. Darren Emerson en a été le troisième membre de 1990 à 2000.", en: "British electronic group formed in 1987, born of Karl Hyde and Rick Smith meeting in Cardiff. Their progressive techno laced with spoken word took hold with the album Dubnobasswithmyheadman (1994), then with \"Born Slippy .NUXX\", carried by the Trainspotting soundtrack in 1996. Darren Emerson was the third member from 1990 to 2000." }, origin: "Cardiff, Royaume-Uni", since: 1987, labels: ["Junior Boy's Own", "Cooking Vinyl"], sources: ["https://en.wikipedia.org/wiki/Underworld_(band)"], photo: { file: "underworld.webp", author: "Torrensmike", license: "CC BY-SA 4.0", page: "https://commons.wikimedia.org/wiki/File:UW_AllyPally_2017_(cropped).jpg" } }, // Underworld
  "victor-ruiz": { slug: "victor-ruiz", bio: { fr: "Producteur et DJ brésilien installé à Amsterdam, Victor Ruiz joue une techno mélodique de peak time et revendique une influence rock dans ses productions. Il sort sur Drumcode et a remixé Moby, Stephan Bodzin et Dubfire. Ses sets sont aussi connus pour ses edits non officiels de classiques signés The Prodigy, Robert Miles, Depeche Mode ou Massive Attack.", en: "A Brazilian producer and DJ based in Amsterdam, Victor Ruiz plays peak-time melodic techno and claims a rock influence in his productions. He releases on Drumcode and has remixed Moby, Stephan Bodzin and Dubfire. His sets are also known for his unofficial edits of classics by The Prodigy, Robert Miles, Depeche Mode and Massive Attack." }, origin: "Brésil", labels: ["Drumcode"], sources: ["https://www.drumcode.se/artists/victor-ruiz"] }, // Victor Ruiz
  "vini-vici": { slug: "vini-vici", bio: { fr: "Vini Vici est un duo israélien de psytrance formé par Matan Kadosh et Aviram Saharai, basé à Afula. Les deux producteurs travaillaient ensemble depuis 2001 sous le nom Sesto Sento avant d'adopter Vini Vici en 2013. Leur remix de « Free Tibet » de Hilight Tribe puis « Great Spirit » (2016), avec Armin van Buuren, ont fait passer la psytrance sur les grandes scènes ; ils ont lancé le label Alteza Records en 2018.", en: "Vini Vici are an Israeli psytrance duo made up of Matan Kadosh and Aviram Saharai, based in Afula. The pair had worked together since 2001 as Sesto Sento before taking the Vini Vici name in 2013. Their remix of Hilight Tribe's \"Free Tibet\" and then \"Great Spirit\" (2016) with Armin van Buuren carried psytrance onto festival main stages; they launched the label Alteza Records in 2018." }, origin: "Afula, Israël", since: 2013, labels: ["Alteza Records"], sources: ["https://en.wikipedia.org/wiki/Vini_Vici"] }, // Vini Vici
  "vladimir-cauchemar": { slug: "vladimir-cauchemar", bio: { fr: "Vladimir Cauchemar, de son vrai nom Guillaume Brière, né le 17 décembre 1978 à Reims, est un DJ, compositeur et producteur français. Membre des groupes The Shoes et The Film, il se fait connaître en solo avec le single Aulos, publié sur Ed Banger Records. Il se produit toujours masqué, derrière une tête de mort, et a produit des titres pour Lomepal, Roméo Elvis et Vald.", en: "Vladimir Cauchemar, real name Guillaume Brière, born 17 December 1978 in Reims, is a French DJ, composer and producer. A member of the bands The Shoes and The Film, he broke through solo with the single \"Aulos\" on Ed Banger Records. He always performs masked, behind a skull, and has produced tracks for Lomepal, Roméo Elvis and Vald." }, origin: "Reims, France", since: 2017, labels: ["Ed Banger Records", "Lokomotiv Sound"], sources: ["https://fr.wikipedia.org/wiki/Vladimir_Cauchemar", "https://en.wikipedia.org/wiki/Vladimir_Cauchemar"], photo: { file: "vladimir-cauchemar.webp", author: "Ubérant", license: "CC BY-SA 4.0", page: "https://commons.wikimedia.org/wiki/File:Vladimir_Cauchemar,_lors_du_ZEVENT_2025.jpg" } }, // Vladimir Cauchemar
  "vortek-s": { slug: "vortek-s", bio: { fr: "Vortek's est un DJ et producteur français originaire de Cherbourg, issu de la scène free party et des styles tribe, acidcore et hardtek. Son signe distinctif : des rythmiques massives, des textures acid et des nappes immersives, sur des morceaux comme « Darkness ». Il collabore régulièrement avec Felckin, Venom, Teksa ou D-Frek, et ses disques paraissent notamment sur Omny Lab, Acid Pirate et Underground Tekno.", en: "Vortek's is a French DJ and producer from Cherbourg who came up through the free party scene and its tribe, acidcore and hardtek strands. His trademark is heavy rhythm work, acid textures and immersive pads, heard on tracks such as \"Darkness\". He works regularly with Felckin, Venom, Teksa and D-Frek, and releases on labels including Omny Lab, Acid Pirate and Underground Tekno." }, origin: "Cherbourg, France", labels: ["Omny Lab", "Acid Pirate", "Underground Tekno"], sources: ["https://dreamnation.fr/en/artiste/vorteks/", "https://download.undergroundtekno.com/en/artists/vorteks/tracks"] }, // Vortek's
  "warface": { slug: "warface", bio: { fr: "Warface est un projet néerlandais de raw hardstyle porté par Youri Claessens et Remco-Jan Prevoo, ce dernier également connu comme le producteur hardcore Triax. Un seul des deux membres assure les sets, masqué et en tenue militaire. Le projet publie sur End of Line Recordings, Defqon.1 Records et Intents Records, avec des titres comme « Embrace The Madness », « Filthy Rave » avec Rebelion ou « To The Stars » avec Paul Elstak.", en: "Warface is a Dutch raw hardstyle project run by Youri Claessens and Remco-Jan Prevoo, the latter also known as hardcore producer Triax. Only one of the two performs the DJ sets, masked and in military dress. The project releases on End of Line Recordings, Defqon.1 Records and Intents Records, with tracks such as \"Embrace The Madness\", \"Filthy Rave\" with Rebelion and \"To The Stars\" with Paul Elstak." }, origin: "Pays-Bas", labels: ["End of Line Recordings"], sources: ["https://hardstyle.com/en/artists/warface", "https://hardstylemag.com/catch-up-interview-with-warface/", "https://www.discogs.com/artist/1120960"] }, // Warface
  "yanamaste": { slug: "yanamaste", bio: { fr: "Yanamaste, de son vrai nom Irakli Danelia, est un DJ et producteur géorgien né et grandi à Batumi. Musicien de formation — piano dès six ans, percussions traditionnelles géorgiennes, huit ans dans l'ensemble national de danse —, il découvre le club à 16 ans et se tourne vers la techno. Il travaille beaucoup au synthétiseur modulaire et joue notamment à Awakenings, à Amsterdam.", en: "Yanamaste, real name Irakli Danelia, is a Georgian DJ and producer born and raised in Batumi. A trained musician — piano from the age of six, traditional Georgian percussion, eight years in the national dance ensemble — he first walked into a club at 16 and turned to techno. He works extensively with modular synthesisers and has played at Awakenings in Amsterdam, among others." }, origin: "Batumi, Géorgie", sources: ["https://surefire.agency/yanamaste", "https://www.numeronetherlands.com/in-conversation-with/in-conversation-with-yanamaste"] }, // Yanamaste
  "yoshiko": { slug: "yoshiko", bio: { fr: "Yoshiko, de son vrai nom Giada Morone, est une DJ de hardcore née en Italie d'une famille aux racines japonaises et brésiliennes — son nom de scène est un hommage à sa tante. Venue à la hardstyle puis au hardcore à l'adolescence, elle s'installe à Amsterdam à vingt-deux ans pour en faire son métier. Elle joue depuis sur les grandes scènes hard dance, de Defqon.1 à Harmony of Hardcore.", en: "Yoshiko, real name Giada Morone, is a hardcore DJ born in Italy to a family with Japanese and Brazilian roots — her stage name is a tribute to her aunt. She came to hardstyle and then hardcore as a teenager and moved to Amsterdam at twenty-two to make it her career. She has since played the major hard dance stages, from Defqon.1 to Harmony of Hardcore." }, origin: "Italie, installée à Amsterdam", sources: ["https://www.hardcoreitalia.it/en/artists/yoshiko"] }, // Yoshiko
  "zara-larsson": { slug: "zara-larsson", bio: { fr: "Zara Larsson est une chanteuse et autrice-compositrice suédoise née en 1997 à Solna, dans la banlieue de Stockholm. Elle s'est fait connaître à dix ans en remportant la deuxième saison de l'émission Talang en 2008, puis avec le single « Uncover » en 2013, numéro un en Suède. Sa pop teintée de house et de dance a franchi les frontières avec « Lush Life » en 2015 et « Symphony », avec Clean Bandit, numéro un au Royaume-Uni. Elle a lancé son propre label, Sommer House, en 2022, et son album « Midnight Sun » (2025) lui a valu sa première nomination aux Grammy Awards.", en: "Zara Larsson is a Swedish singer and songwriter born in 1997 in Solna, on the edge of Stockholm. She first became known at ten by winning the second season of the talent show Talang in 2008, then with the single \"Uncover\" in 2013, a number one in Sweden. Her house- and dance-inflected pop crossed over with \"Lush Life\" in 2015 and \"Symphony\" with Clean Bandit, a UK number one. She launched her own label, Sommer House, in 2022, and her album \"Midnight Sun\" (2025) earned her a first Grammy nomination." }, origin: "Solna, Suède", since: 2008, labels: ["Sommer House", "Epic Records"], sources: ["https://en.wikipedia.org/wiki/Zara_Larsson"], photo: { file: "zara-larsson.webp", author: "Hellomoto100", license: "CC BY-SA 4.0", page: "https://commons.wikimedia.org/wiki/File:Zara_Larsson_Midnight_Sun_European_Tour_(cropped)_(cropped).jpg" } }, // Zara Larsson
};
/* BIOS:end */

export const bioFor = (slug: string): ArtistBio | undefined => BIOS[slug];

export const bioText = (b: ArtistBio, lang: Lang): string => (lang === "fr" ? b.bio.fr : b.bio.en);

/** How many artist pages currently carry a researched bio — used by the audit script. */
export const BIO_COUNT = Object.keys(BIOS).length;
